public class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;

        public Line() {}
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;

        public Order() {}
    }

    public static Order parse(String body) {
        // --- null / blank body ---
        if (body == null || body.trim() == '') {
            throw new PayloadException('Order payload must not be null or blank.');
        }

        // --- must be valid JSON ---
        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Order payload is not valid JSON: ' + e.getMessage());
        }

        // --- must be a JSON object ---
        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Order payload must be a JSON object.');
        }
        Map<String, Object> root = (Map<String, Object>) parsed;

        // --- order number: required, non-blank ---
        Object numberValue = root.get('number');
        if (numberValue == null || !(numberValue instanceof String) || ((String) numberValue).trim() == '') {
            throw new PayloadException('Order payload must contain a non-blank "number".');
        }

        Order order = new Order();
        order.orderNumber = (String) numberValue;

        // --- optional date (ISO yyyy-MM-dd) ---
        Object dateValue = root.get('date');
        if (dateValue instanceof String) {
            String dateStr = (String) dateValue;
            try {
                // JSON.deserializeUntyped does not attempt to coerce the value, so parse explicitly.
                order.orderDate = Date.valueOf(dateStr); // not used for ISO strings; replaced below
            } catch (Exception e) {
                // handled below by strict manual parsing
            }
            order.orderDate = parseIsoDate(dateStr);
        }

        // --- optional currency ---
        Object currencyValue = root.get('currency');
        if (currencyValue instanceof String) {
            order.currencyCode = (String) currencyValue;
        }

        // --- optional customer.email ---
        Object customerValue = root.get('customer');
        if (customerValue instanceof Map<String, Object>) {
            Map<String, Object> customer = (Map<String, Object>) customerValue;
            Object emailValue = customer.get('email');
            if (emailValue instanceof String) {
                order.customerEmail = (String) emailValue;
            }
        }

        // --- lines (optional; empty list when missing or null) ---
        order.lines = new List<Line>();
        Object linesValue = root.get('lines');
        if (linesValue instanceof List<Object>) {
            List<Object> rawLines = (List<Object>) linesValue;
            Decimal total = 0;
            for (Object rawLine : rawLines) {
                if (!(rawLine instanceof Map<String, Object>)) {
                    throw new PayloadException('Each entry in "lines" must be a JSON object.');
                }
                Map<String, Object> rawLineMap = (Map<String, Object>) rawLine;

                Line line = new Line();

                // sku: required, must be a non-empty string
                Object skuValue = rawLineMap.get('sku');
                if (skuValue == null || !(skuValue instanceof String) || ((String) skuValue).trim() == '') {
                    throw new PayloadException('Each line must contain a "sku".');
                }
                line.sku = (String) skuValue;

                // quantity: required, must be a positive number
                Object quantityValue = rawLineMap.get('quantity');
                if (quantityValue == null) {
                    throw new PayloadException('Line "' + line.sku + '" must contain a positive "quantity".');
                }
                Integer quantity;
                try {
                    quantity = toInteger(quantityValue);
                } catch (Exception e) {
                    throw new PayloadException('Line "' + line.sku + '" has an invalid "quantity".');
                }
                if (quantity == null || quantity <= 0) {
                    throw new PayloadException('Line "' + line.sku + '" must contain a positive "quantity".');
                }
                line.quantity = quantity;

                // unitPrice: required, must be a non-negative number
                Object unitPriceValue = rawLineMap.get('unitPrice');
                if (unitPriceValue == null) {
                    throw new PayloadException('Line "' + line.sku + '" must contain a non-negative "unitPrice".');
                }
                Decimal unitPrice;
                try {
                    unitPrice = toDecimal(unitPriceValue);
                } catch (Exception e) {
                    throw new PayloadException('Line "' + line.sku + '" has an invalid "unitPrice".');
                }
                if (unitPrice == null || unitPrice < 0) {
                    throw new PayloadException('Line "' + line.sku + '" must contain a non-negative "unitPrice".');
                }
                line.unitPrice = unitPrice;

                // discount: optional fraction between 0 and 1; missing or null -> 0
                Object discountValue = rawLineMap.get('discount');
                Decimal discount = 0;
                if (discountValue != null) {
                    try {
                        discount = toDecimal(discountValue);
                    } catch (Exception e) {
                        throw new PayloadException('Line "' + line.sku + '" has an invalid "discount".');
                    }
                }
                line.discount = discount;

                // lineTotal = quantity * unitPrice * (1 - discount), rounded half up to 2 dp
                Decimal rawTotal = line.quantity * line.unitPrice * (1 - line.discount);
                line.lineTotal = roundHalfUp(rawTotal, 2);
                total += line.lineTotal;
            }
            order.total = total;
        } else {
            order.total = 0;
        }

        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order != null ? order.orderNumber : null);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order != null && order.lines != null ? order.lines.size() : 0);
        ack.put('total', order != null && order.total != null ? order.total : 0);
        return JSON.serialize(ack);
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static Decimal toDecimal(Object value) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf((Double) value);
        }
        if (value instanceof String) {
            String s = ((String) value).trim();
            if (s == '') {
                return null;
            }
            try {
                return Decimal.valueOf(s);
            } catch (Exception e) {
                return null;
            }
        }
        return null;
    }

    private static Integer toInteger(Object value) {
        if (value instanceof Integer) {
            return (Integer) value;
        }
        if (value instanceof Long) {
            Long l = (Long) value;
            if (l >= Integer.valueOf('-2147483648') && l <= Integer.valueOf('2147483647')) {
                return Integer.valueOf(String.valueOf(l));
            }
            return null;
        }
        if (value instanceof Decimal) {
            Decimal d = (Decimal) value;
            if (d == d.round()) {
                return Integer.valueOf(d.format());
            }
            return null;
        }
        if (value instanceof String) {
            String s = ((String) value).trim();
            try {
                return Integer.valueOf(s);
            } catch (Exception e) {
                return null;
            }
        }
        return null;
    }

    private static Decimal roundHalfUp(Decimal value, Integer scale) {
        if (value == null) {
            return null;
        }
        Decimal scaled = value.setScale(scale + 5, RoundingMode.HALF_UP);
        return scaled.setScale(scale, RoundingMode.HALF_UP);
    }

    private static Date parseIsoDate(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        List<String> parts = trimmed.split('-', 3);
        if (parts.size() != 3) {
            throw new PayloadException('Invalid ISO date for "date": ' + value);
        }
        try {
            Integer year = Integer.valueOf(parts[0]);
            Integer month = Integer.valueOf(parts[1]);
            Integer day = Integer.valueOf(parts[2]);
            return Date.newInstance(year, month, day);
        } catch (Exception e) {
            throw new PayloadException('Invalid ISO date for "date": ' + value);
        }
    }
}
