    }

    // ---- Request contract -------------------------------------------------

    @isTest
    static void testRequestContract() {
        reset();
        Account acct = newAccount();
        acct.BillingCity = 'Àuthorityville'; // include non-ASCII to pin serialization
        runVerify(new MockResponse(200, '{"status":"VERIFIED"}'), acct);
