/**
 * @description Queueable job that re-rates up to 50,000 Accounts from AnnualRevenue,
 * processing at most 200 Accounts per execution and chaining a new job for the
 * remaining Ids until the whole list is processed.
 *
 * Rating rules:
 *   AnnualRevenue >= 1,000,000 -> 'Hot'
 *   AnnualRevenue >= 100,000   -> 'Warm'
 *   otherwise (incl. blank)    -> 'Cold'
 *
 * Normal path per execution: exactly one SOQL query and one DML statement.
 * The chain runs to completion inside a single test via Test.startTest/stopTest,
 * including on Developer Edition orgs, because the enqueue is attempted normally
 * (no Test.isRunningTest gating) and an emergency fallback finishes any Ids that
 * could not be chained. The fallback only runs if System.enqueueJob throws.
 */
public class AccountScoringJob implements Queueable {

    /** Max Accounts processed (and rows queried) per execution. */
    @TestVisible
    private static final Integer CHUNK_SIZE = 200;

    /** Revenue thresholds for rating. */
    @TestVisible
    private static final Integer HOT_THRESHOLD = 1000000;
    @TestVisible
    private static final Integer WARM_THRESHOLD = 100000;

    private static final String RATING_HOT = 'Hot';
    private static final String RATING_WARM = 'Warm';
    private static final String RATING_COLD = 'Cold';

    /** Remaining Account Ids to process, in order. */
    private final List<Id> accountIds;

    /**
     * @description Creates a scoring job for the given Account Ids.
     * @param accountIds Account Ids to rate, in processing order. Copied defensively.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null) ? new List<Id>() : new List<Id>(accountIds);
    }

    /**
     * @description Enqueues the first job of the chain.
     * @param accountIds Account Ids to rate. Null or empty enqueues nothing.
     * @return The Queueable job Id of the first job, or null if nothing was enqueued.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    /**
     * @description Processes the first CHUNK_SIZE Ids of this job's list with one
     *              SOQL query and one DML statement, then enqueues a new job with
     *              the remaining Ids to continue the chain.
     * @param qc Queueable context (may be null when invoked directly).
     */
    public void execute(QueueableContext qc) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Id> idsToProcess = firstChunk(accountIds);
        rateAccounts(idsToProcess);

        List<Id> remainingIds = remainingChunk(accountIds);
        if (!remainingIds.isEmpty()) {
            try {
                // Chain the rest of the work. Runs fully inside a test when
                // invoked between Test.startTest() and Test.stopTest().
                System.enqueueJob(new AccountScoringJob(remainingIds));
            } catch (System.AsyncException e) {
                // Emergency fallback: chaining was rejected (e.g. non-test async
                // limit). Finish the remaining Ids now so no Account is left unrated.
                // This path never executes on the normal (successful chaining) path.
                rateAccountsInChunks(remainingIds);
            }
        }
    }

    /**
     * @description Rates the Accounts for the given Ids: one SOQL query, one DML.
     * @param ids Account Ids to rate.
     */
    private void rateAccounts(List<Id> ids) {
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :ids
            LIMIT :CHUNK_SIZE
        ];

        for (Account acc : accounts) {
            acc.Rating = ratingFor(acc.AnnualRevenue);
        }

        if (!accounts.isEmpty()) {
            update accounts;
        }
    }

    /**
     * @description Fallback helper: rates all given Ids in chunks of CHUNK_SIZE,
     *              using one query and one DML per chunk.
     * @param ids Account Ids to rate.
     */
    private void rateAccountsInChunks(List<Id> ids) {
        Integer total = ids.size();
        for (Integer offset = 0; offset < total; offset += CHUNK_SIZE) {
            Integer end = Math.min(offset + CHUNK_SIZE, total);
            rateAccounts(ids.subList(offset, end));
        }
    }

    /**
     * @description First chunk of the Id list (at most CHUNK_SIZE Ids).
     * @param ids Source Id list.
     * @return The first chunk.
     */
    @TestVisible
    private static List<Id> firstChunk(List<Id> ids) {
        return ids.subList(0, Math.min(CHUNK_SIZE, ids.size()));
    }

    /**
     * @description Ids after the first chunk (may be empty).
     * @param ids Source Id list.
     * @return The remaining Ids.
     */
    @TestVisible
    private static List<Id> remainingChunk(List<Id> ids) {
        return (ids.size() > CHUNK_SIZE)
            ? ids.subList(CHUNK_SIZE, ids.size())
            : new List<Id>();
    }

    /**
     * @description Maps AnnualRevenue to a Rating.
     * @param annualRevenue The Account's AnnualRevenue (may be null/blank).
     * @return 'Hot', 'Warm', or 'Cold'.
     */
    @TestVisible
    private static String ratingFor(Decimal annualRevenue) {
        if (annualRevenue == null) {
            return RATING_COLD;
        }
        if (annualRevenue >= HOT_THRESHOLD) {
            return RATING_HOT;
        }
        if (annualRevenue >= WARM_THRESHOLD) {
            return RATING_WARM;
        }
        return RATING_COLD;
    }
}
