public without sharing class ErpSyncFinalizer implements Finalizer {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(FinalizerContext ctx) {
        FB_Job_Log__c log = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c = attempt
        );

        if (ctx.getResult() == ParentJobResult.SUCCESS) {
            log.Status__c = 'Success';
            insert log;
            return;
        }

        log.Status__c = 'Failed';
        String errorMessage = ctx.getException().getMessage();
        if (String.isNotBlank(errorMessage) && errorMessage.length() > 255) {
            errorMessage = errorMessage.substring(0, 255);
        }
        log.Error__c = errorMessage;
        insert log;

        // Retry up to three total attempts; nothing enqueued after the third failure.
        if (attempt < 3) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }
}
