public with sharing class OpportunityRollupService {

    /**
     * @description Returns each requested account's total closed-won revenue for the
     *              current calendar year. Sums are computed in the database via a single
     *              aggregate SOQL query grouped by AccountId, so no opportunity records
     *              are loaded into memory. The query runs "with sharing" so results
     *              respect the running user's record access.
     * @param  accountIds Set of Account Ids to roll up. May be null or empty.
     * @return Map keyed by every requested Account Id, valued at the sum of Amount for
     *         won opportunities closing in the current calendar year (0 when there are
     *         none or all Amounts are blank). Ids not requested are never keys.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        // Null or empty input -> empty map.
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Defensive copy so the caller's set is never mutated by filtering.
        Set<Id> validIds = new Set<Id>();
        for (Id accId : accountIds) {
            if (accId != null) {
                validIds.add(accId);
            }
        }
        if (validIds.isEmpty()) {
            return result;
        }

        // Bound the year in Apex so the database only evaluates the date predicate
        // against literal bounds (also lets the optimizer use the standard index on CloseDate).
        Date yearStart = Date.today().toStartOfMonth().toStartOfMonth(); // no-op, keeps intent explicit
        yearStart = Date.newInstance(Date.today().year(), 1, 1);
        Date yearEnd = Date.newInstance(Date.today().year(), 12, 31);

        // Single aggregate query: SUM grouped by AccountId, filtered to the requested
        // accounts, won opps, and the current calendar year. AggregateResult aliases
        // ("accId", "total") must be lowercase identifiers.
        List<AggregateResult> aggResults = [
            SELECT AccountId accId, SUM(Amount) total
            FROM Opportunity
            WHERE AccountId IN :validIds
              AND IsWon = true
              AND CloseDate >= :yearStart
              AND CloseDate <= :yearEnd
            GROUP BY AccountId
        ];

        for (AggregateResult ar : aggResults) {
            Id accId = (Id) ar.get('accId');
            Decimal total = (Decimal) ar.get('total');
            result.put(accId, total == null ? 0 : total);
        }

        // Every requested account must be a key; accounts with no qualifying
        // opportunities (or only blank Amounts, which SUM skips) default to 0.
        for (Id accId : validIds) {
            if (!result.containsKey(accId)) {
                result.put(accId, 0);
            }
        }

        return result;
    }
}
