public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    public static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> records)
    {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }

    public override void onAfterInsert()
    {
        startFulfilmentForQualifiedOpportunities();
    }

    public override void onAfterUpdate(Map<Id, sObject> existingRecords)
    {
        startFulfilmentForQualifiedOpportunities((Map<Id, Opportunity>) existingRecords);
    }

    private void startFulfilmentForQualifiedOpportunities()
    {
        startFulfilmentForQualifiedOpportunities(null);
    }

    private void startFulfilmentForQualifiedOpportunities(Map<Id, Opportunity> existingRecords)
    {
        Set<Id> opportunityIds = new Set<Id>();

        for (Opportunity record : (List<Opportunity>) this.getRecords())
        {
            if (isClosedWon(record) && isNewlyClosedWon(record, existingRecords))
            {
                opportunityIds.add(record.Id);
            }
        }

        if (opportunityIds.isEmpty())
        {
            return;
        }

        IOpportunityFulfilmentService service =
            (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
        service.startFulfilment(opportunityIds);
    }

    private Boolean isClosedWon(Opportunity record)
    {
        return record.StageName == STAGE_CLOSED_WON;
    }

    private Boolean isNewlyClosedWon(Opportunity record, Map<Id, Opportunity> existingRecords)
    {
        // On insert there is no pre-existing record, so a won insert always qualifies.
        if (existingRecords == null)
        {
            return true;
        }

        // On update, only qualify when the stage changed to Closed Won from any other stage.
        Opportunity existingRecord = existingRecords.get(record.Id);
        return existingRecord != null && existingRecord.StageName != STAGE_CLOSED_WON;
    }
}
