{
    /** Test-visible accessor for the wrapped records. */
    @TestVisible
    private List<Opportunity> records;

    /**
     * Standard constructor used by the library when building the domain
     * from a list of records.
     */
    public Opportunities(List<Opportunity> sObjectList)
    {
        super(sObjectList);
        // Keep a typed reference to the wrapped records for bulk-safe logic.
        records = (List<Opportunity>) RecordList;
    }

    /**
     * Constructor used by the library when a query result is passed in.
     */
    public Opportunities(List<SObject> sObjectList)
    {
        super(sObjectList);
        // Keep a typed reference to the wrapped records for bulk-safe logic.
        records = (List<Opportunity>) RecordList;
    }

    /**
     * Standard inner class the library uses to construct this domain class
     * dynamically (e.g. via fflib_SObjectDomain.triggerHandler and
     * Application domain factory registrations).
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    /**
     * Called by fflib_SObjectDomain.triggerHandler on before insert.
     * Applies field defaults only for newly created records and only when
     * the fields were left blank by the caller.
     */
    public override void onApplyDefaults()
    {
        applyDefaults();
    }

    /**
     * Also handled through onBeforeInsert so the defaults are applied during
     * the before insert context, keeping values visible to validation rules,
     * workflow and any before-insert logic in the same transaction.
     */
    public override void onBeforeInsert()
    {
        applyDefaults();
    }

    /**
     * Defaults are deliberately NOT applied on update; no onBeforeUpdate
     * override is implemented for that purpose.
     */
    private void applyDefaults()
    {
        Date defaultCloseDate = Date.today().addDays(30);

        for (Opportunity opp : records)
        {
            // Only default when the record is being created (never on update)
            // and only when the user has not supplied a value.
            if (isCreateContext && opp.CloseDate == null)
            {
                opp.CloseDate = defaultCloseDate;
            }
            if (isCreateContext && opp.Type == null)
            {
                opp.Type = 'New Customer';
            }
        }
    }
}
