public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    public static final String RULE_NEGATIVE_AMOUNT = 'AmountMustNotBeNegative';
    public static final String RULE_WON_AMOUNT_LOCK = 'AmountLockedOnWonOpportunity';

    private static final String MSG_NEGATIVE_AMOUNT = 'Amount cannot be negative.';
    private static final String MSG_WON_AMOUNT_LOCK = 'Amount cannot change on a won opportunity.';

    // Pre-update Amount values, captured in the before-update phase so that the
    // validation hook can compare them against the updated values without any SOQL.
    private Map<Id, Decimal> originalAmountsById;

    public Opportunities(List<Opportunity> records)
    {
        super(records);
    }

    public Opportunities(List<Opportunity> records, fflib_SObjectDomain.IConfiguration config)
    {
        super(records, config);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    public override void onBeforeUpdate()
    {
        // Bulk-safe, SOQL-free capture of the pre-update Amounts for the won-lock rule.
        originalAmountsById = new Map<Id, Decimal>();
        for (SObject oldRecord : getOriginal())
        {
            originalAmountsById.put(oldRecord.Id, (Decimal) oldRecord.get(Opportunity.Amount));
        }
    }

    public override void onValidate()
    {
        // Rule 1: on insert and on update, Amount must not be negative.
        if (isInsert() || isUpdate())
        {
            addValidationRule(
                RULE_NEGATIVE_AMOUNT,
                new NegativeAmountRule()
            );
        }

        // Rule 2: on update, a record that was already Closed Won before the update
        // cannot have its Amount changed. Changing the amount while simultaneously
        // closing the opportunity as won is allowed.
        if (isUpdate())
        {
            addValidationRule(
                RULE_WON_AMOUNT_LOCK,
                new WonAmountLockRule()
            );
        }
    }

    private void addValidationRule(String ruleName, fflib_SObjectDomain.IValidationRule rule)
    {
        ValidationRules rules = new ValidationRules(this, ruleName);
        rules.addRule(rule);
        rules.invoke();
    }

    // Rule 1: Amount must not be negative.
    private class NegativeAmountRule implements fflib_SObjectDomain.IValidationRule
    {
        public void validate(fflib_SObjectDomain.IValidationResult result)
        {
            for (SObject record : result.getRecords())
            {
                Decimal amount = (Decimal) record.get(Opportunity.Amount);
                if (amount == null || amount >= 0)
                {
                    continue;
                }
                result.recordError(
                    MSG_NEGATIVE_AMOUNT,
                    record,
                    Opportunity.Amount
                );
            }
        }
    }

    // Rule 2: Amount cannot change on an opportunity that was already Closed Won
    // before the current update.
    private class WonAmountLockRule implements fflib_SObjectDomain.IValidationRule
    {
        public void validate(fflib_SObjectDomain.IValidationResult result)
        {
            Opportunities domain = (Opportunities) result.getDomain();
            Map<Id, Decimal> originalAmounts = domain.originalAmountsById;
            if (originalAmounts == null)
            {
                // No before-update snapshot available (e.g. validate() invoked
                // outside a trigger context); the rule cannot be evaluated.
                return;
            }

            for (SObject record : result.getRecords())
            {
                if (!originalAmounts.containsKey(record.Id))
                {
                    continue;
                }
                if (!String.valueOf(record.get(Opportunity.StageName)).equals('Closed Won'))
                {
                    continue;
                }
                Decimal originalAmount = originalAmounts.get(record.Id);
                if (record.get(Opportunity.Amount) == originalAmount)
                {
                    continue;
                }
                result.recordError(
                    MSG_WON_AMOUNT_LOCK,
                    record,
                    Opportunity.Amount
                );
            }
        }
    }
}
