public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    public static final String STAGE_CLOSED_WON = 'Closed Won';

    private static final String MSG_AMOUNT_NEGATIVE = 'Amount cannot be negative.';
    private static final String MSG_AMOUNT_LOCKED_ON_WON = 'Amount cannot change on a won opportunity.';

    public Opportunities(List<Opportunity> records)
    {
        super(records);
    }

    public Opportunities(List<Opportunity> records, fflib_SObjectDomain.IConfiguration configuration)
    {
        super(records, configuration);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    public override void onValidate()
    {
        validateAmountIsNotNegative();

        // Rule 2 applies only in update context, where pre-update (original) values exist
        if (Trigger.isUpdate)
        {
            validateAmountUnchangedForAlreadyWonOpportunities();
        }
    }

    // Rule 1: on insert and on update, Amount must not be negative.
    private void validateAmountIsNotNegative()
    {
        for (Opportunity record : (List<Opportunity>) Records)
        {
            if (record.Amount != null && record.Amount < 0)
            {
                error(MSG_AMOUNT_NEGATIVE, record, Opportunity.Amount);
            }
        }
    }

    // Rule 2: on update, an opportunity whose stage was already Closed Won before the
    // update cannot have its Amount changed. Closing as won while changing the amount
    // in the same update is allowed (old stage is not yet Closed Won in that case).
    private void validateAmountUnchangedForAlreadyWonOpportunities()
    {
        List<SObject> originalRecords = getOriginal();
        if (originalRecords == null || originalRecords.isEmpty())
        {
            return;
        }

        Map<Id, SObject> originalRecordsById = new Map<Id, SObject>(originalRecords);

        for (Opportunity record : (List<Opportunity>) Records)
        {
            SObject originalRecord = originalRecordsById.get(record.Id);
            if (originalRecord == null)
            {
                continue;
            }

            String originalStage = (String) originalRecord.get(Opportunity.StageName);
            if (!STAGE_CLOSED_WON.equals(originalStage))
            {
                continue;
            }

            Decimal originalAmount = (Decimal) originalRecord.get(Opportunity.Amount);
            if (record.Amount != originalAmount)  // Apex equality is null-safe
            {
                error(MSG_AMOUNT_LOCKED_ON_WON, record, Opportunity.Amount);
            }
        }
    }
}
