/**
 * Domain class for Opportunity, implemented with the fflib Apex Enterprise
 * Patterns domain pattern. Enforces the following validation rules from the
 * domain's validation hook (onValidate):
 *
 *   1. On insert and on update, Amount must not be negative.
 *   2. On update, an opportunity whose stage was already 'Closed Won' before
 *      the update cannot have its Amount changed. Closing an opportunity as
 *      won and changing its amount in the same update is allowed.
 *
 * Each error is raised on the Amount field of the offending record only, so
 * the other records in the same bulk DML still save.
 */
public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    private static final String MSG_AMOUNT_NEGATIVE = 'Amount cannot be negative.';
    private static final String MSG_AMOUNT_LOCKED_ON_WON =
        'Amount cannot change on a won opportunity.';

    public Opportunities(List<Opportunity> records)
    {
        super(records);
    }

    public Opportunities(List<Opportunity> records, fflib_SObjectDomain.IConfiguration configuration)
    {
        super(records, configuration);
    }

    /**
     * Standard fflib constructable inner class, used by
     * fflib_SObjectDomain.triggerHandler to instantiate this domain.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    /**
     * Validation hook. fflib_SObjectDomain.triggerHandler invokes this during
     * the before insert and before update phases, so the rules below apply
     * exactly to insert and update operations. Bulk-safe and SOQL-free: the
     * rules only use in-memory record values (including the fflib-managed
     * pre-update originals from Trigger.oldMap).
     */
    public override void onValidate()
    {
        validateAmountIsNotNegative();
        validateAmountUnchangedForAlreadyWonOpportunities();
    }

    /**
     * Rule 1: on insert and on update, Amount must not be negative.
     * A null Amount is not negative and therefore passes.
     */
    private void validateAmountIsNotNegative()
    {
        for (Opportunity record : (List<Opportunity>) Records)
        {
            if (record.Amount != null && record.Amount < 0)
            {
                error(MSG_AMOUNT_NEGATIVE, record, Opportunity.Amount);
            }
        }
    }

    /**
     * Rule 2: on update, an opportunity whose stage was already 'Closed Won'
     * before the update cannot have its Amount changed.
     *
     * The pre-update values are taken from getOriginal(), which
     * fflib_SObjectDomain.triggerHandler populates from Trigger.oldMap during
     * update trigger execution (no SOQL required). When no original records
     * are available (e.g. insert context, where this rule does not apply),
     * the rule is skipped. Apex equality on Decimal is null-safe, so null to
     * non-null Amount transitions are correctly treated as changes.
     */
    private void validateAmountUnchangedForAlreadyWonOpportunities()
    {
        List<SObject> originalRecords = getOriginal();
        if (originalRecords == null || originalRecords.isEmpty())
        {
            // No pre-update state (insert context or non-update invocation).
            return;
        }

        Map<Id, SObject> originalRecordsById = new Map<Id, SObject>(originalRecords);

        for (Opportunity record : (List<Opportunity>) Records)
        {
            SObject originalRecord = originalRecordsById.get(record.Id);
            if (originalRecord == null)
            {
                continue;
            }

            // The stage as it was BEFORE this update decides whether the
            // opportunity was already won.
            String originalStage = (String) originalRecord.get(Opportunity.StageName);
            if (!STAGE_CLOSED_WON.equals(originalStage))
            {
                continue;
            }

            Decimal originalAmount = (Decimal) originalRecord.get(Opportunity.Amount);
            if (record.Amount != originalAmount)
            {
                error(MSG_AMOUNT_LOCKED_ON_WON, record, Opportunity.Amount);
            }
        }
    }
}
