public inherited sharing class CaseEscalationService {

    public class EscalationException extends Exception {}

    public static void escalate(Set<Id> caseIds, String reason) {
        // Validate the reason first, before reading or writing anything.
        if (String.isBlank(reason)) {
            throw new EscalationException('An escalation reason is required.');
        }

        // Nothing to do for a null or empty set of case ids.
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        // Load the cases through the fflib selector (mockable via Application.Selector.setMock).
        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        Boolean hasWork = false;
        for (Case c : cases) {
            // Skip closed cases and cases that are already escalated.
            if (c.Status == 'Closed' || c.IsEscalated == true) {
                continue;
            }

            hasWork = true;

            // Update the case.
            Case escalatedCase = new Case(
                Id = c.Id,
                IsEscalated = true,
                Priority = 'High'
            );
            uow.registerDirty(escalatedCase);

            // Create the escalation task owned by the case owner.
            Task task = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = Date.today().addDays(1),
                Priority = 'High'
            );
