public inherited sharing class ContactPhoneCleanup {

    /**
     * Normalizes the Phone field of the requested contacts so that only digits
     * and a single leading '+' remain, then persists them with a partial-success
     * update.
     *
     * @param contactIds  Ids of the contacts to process (up to 200 at a time).
     * @return Map from the Id of each contact that could NOT be saved to the
     *         message of its first save error. Empty when everything saved.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorsById = new Map<Id, String>();
        if (contactIds == null || contactIds.isEmpty()) {
            return errorsById;
        }

        // Query only what we need. Contacts without a Phone value are left
        // untouched (no DML attempt), as required.
        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
        ];

        for (Contact con : contacts) {
            if (String.isBlank(con.Phone)) {
                continue; // no phone -> leave out
            }
            // Strip everything that is not a digit or '+'.
            con.Phone = con.Phone.replaceAll('[^0-9+]', '');
        }

        // Single DML call; allRows=true so failed rows come back in the
        // SaveResult list instead of throwing, letting the other rows save.
        List<Database.SaveResult> results = Database.update(contacts, false);

        // SaveResult list is index-aligned with the input list.
        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult result = results[i];
            if (!result.isSuccess()) {
                Contact failed = contacts[i];
                // Report the first error for this record.
                errorsById.put(
                    failed.Id,
                    result.getErrors()[0].getMessage()
                );
            }
        }
        return errorsById;
    }
}
