```apex
public with sharing class PipelineSummary {
    @ReadOnly
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        List<String> stages = new List<String>{
            'Prospecting',
            'Qualification',
            'Proposal/Price Quote',
            'Negotiation/Review'
        };

        Map<String, Decimal> totals = new Map<String, Decimal>{
            'Prospecting' => 0,
            'Qualification' => 0,
            'Proposal/Price Quote' => 0,
            'Negotiation/Review' => 0
        };

        for (String stageName : stages) {
            Decimal total = 0;
            // Aggregate query: SUM ignores null Amounts; if every row is null or
            // there are no rows, the aggregate itself is null, so coalesce to 0.
            for (AggregateResult row : [
                SELECT SUM(Amount) stageTotal
                FROM Opportunity
                WHERE StageName = :stageName
                  AND CloseDate >= :fromDate
                  AND CloseDate <= :toDate
            ]) {
                total = row.get('stageTotal') == null
                    ? 0
                    : (Decimal) row.get('stageTotal');
            }
            totals.put(stageName, total);
        }

        return totals;
    }
}
```

