/**
 * Nightly batch-style closer for stale opportunities.
 *
 * Closes every open opportunity whose CloseDate is strictly before the given
 * cutoff date by setting StageName = 'Closed Lost'. Designed to be called
 * synchronously from a Schedulable class; the caller reports the returned count.
 *
 * Memory/streaming safety: uses a SOQL for loop in its list form so rows are
 * read (and DML'd) in chunks of 200. No intermediate List of all records is
 * ever materialized in heap, so a few thousand (or tens of thousands) of
 * affected rows will not hit heap or DML-row limits, and each chunk update
 * stays well inside the 10,000 DML-row-per-transaction governor limit.
 */
public inherited sharing class StaleOpportunityCloser {

    /** Stage applied to stale opportunities. */
    @TestVisible
    private static final String STALE_CLOSED_STAGE = 'Closed Lost';

    /** Chunk size for SOQL for-loop list form; 200 is the max DML statement size per call. */
    @TestVisible
    private static final Integer CHUNK_SIZE = 200;

    /**
     * Closes all open opportunities with CloseDate strictly before cutoff.
     *
     * @param cutoff  Opportunities with CloseDate >= cutoff stay open (strictly less-than match).
     * @return        Number of opportunities actually moved to Closed Lost.
     */
    public static Integer closeStale(Date cutoff) {
        Integer closedCount = 0;

        // List-form SOQL for loop: every iteration yields at most 200 records
        // (the standard chunk size when no LIMIT is applied inside the loop
        // header), which is also the safe size for a single DML statement.
        for (List<Opportunity> chunk : [
            SELECT Id
            FROM Opportunity
            WHERE IsClosed = false
              AND CloseDate < :cutoff
              AND StageName != :STALE_CLOSED_STAGE
        ]) {
            for (Opportunity opp : chunk) {
                opp.StageName = STALE_CLOSED_STAGE;
            }

            Database.update(chunk, false); // partial success allowed per chunk
            closedCount += chunk.size();
        }

        return closedCount;
    }
}
