```apex
trigger OpportunityTrigger on Opportunity (after insert, after update) {

    // Collect distinct AccountIds so each affected account is recalculated
    // exactly once per transaction, regardless of batch size.
    Set<Id> accountIds = new Set<Id>();

    for (Opportunity opp : Trigger.new) {

        if (opp.AccountId == null) {
            continue; // opportunity without an account: nothing to recalculate
        }

        if (Trigger.isInsert) {
            accountIds.add(opp.AccountId);
        } else {
            // On update, recalculate only when StageName or Amount changed.
            Opportunity old = Trigger.oldMap.get(opp.Id);
            if (opp.StageName != old.StageName || opp.Amount != old.Amount) {
                accountIds.add(opp.AccountId);
            }

            // If the account moved, the old account's rating may change too.
            if (opp.AccountId != old.AccountId) {
                accountIds.add(opp.AccountId);
                if (old.AccountId != null) {
                    accountIds.add(old.AccountId);
                }
            }
        }
    }

    // Delegate to the service, which owns all rating logic.
    AccountRatingService.recalculate(accountIds);
}
```

