     * use in production. This method is provided because the requested nested
     * loop is correct and readable, and it keeps the exact contract asked for.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> result = new List<Id>();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Contact> safeContacts = (contacts == null) ? new List<Contact>() : contacts;

        // Pre-normalize contact emails once per contact instead of once per
        // (lead, contact) pair. Semantics are unchanged; this only avoids
        // re-trimming and re-lowercasing the same contact email 3,000 times.
        List<String> normalizedContactEmails = new List<String>();
        for (Contact c : safeContacts) {
            normalizedContactEmails.add(normalize(c.Email));
        }

        for (Lead l : leads) {
            String leadEmail = normalize(l.Email);
            Id matchedContactId = null;

            if (String.isNotBlank(leadEmail)) {
                for (Integer i = 0; i < safeContacts.size(); i++) {
                    // Blank contact emails can never match; skip them cheaply.
                    String contactEmail = normalizedContactEmails[i];
                    if (String.isNotBlank(contactEmail) && contactEmail.equals(leadEmail)) {
                        matchedContactId = safeContacts[i].Id;
                        break;
                    }
                }
            }

            result.add(matchedContactId);
        }

        return result;
    }

    /**
     * Same behavior and contract as matchByEmail, but O(n + m): builds a
     * map from normalized email to the first contact Id in `contacts` order,
     * then does one lookup per lead. I would use this in production for the
     * stated volumes (up to 3,000 x 3,000), because the nested loop can
     * approach the CPU time limit when run inside the import transaction,
     * while this stays trivially fast. Output is identical.
     */
    public static List<Id> matchByEmailIndexed(List<Lead> leads, List<Contact> contacts) {
        List<Id> result = new List<Id>();
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        Map<String, Id> firstContactIdByEmail = new Map<String, Id>();
        if (contacts != null) {
            for (Contact c : contacts) {
                String key = normalize(c.Email);
                if (String.isNotBlank(key) && !firstContactIdByEmail.containsKey(key)) {
                    firstContactIdByEmail.put(key, c.Id);
                }
            }
        }

        for (Lead l : leads) {
            String key = normalize(l.Email);
            Id matchedContactId = null;
            if (String.isNotBlank(key)) {
                matchedContactId = firstContactIdByEmail.get(key);
            }
            result.add(matchedContactId);
        }

        return result;
    }

    // Lowercase + trim; null-safe. After trimming, an all-whitespace email
    // becomes the empty string, which String.isNotBlank treats as blank.
    private static String normalize(String email) {
        if (email == null) {
            return null;
        }
        String trimmed = email.trim();
        return trimmed.toLowerCase();
    }
}
