```apex
/**
 * AccountCountrySync
 *
 * When an Account's BillingCountry changes, propagate the new country to the
 * MailingCountry of that account's Contacts — but only for contacts whose
 * MailingCountry is either blank, or equal to the account's PREVIOUS
 * BillingCountry. Contacts with any other MailingCountry are left untouched,
 * as are contacts of accounts whose BillingCountry did not change.
 *
 * Bulk-safe design (MDM pushes 200-account batches; org has ~2.3M contacts):
 *  - ONE SOQL statement per transaction, executed once outside all loops,
 *    scoped to just the accounts in this batch (2.3M contacts would blow the
 *    50k query-row limit and is pure over-fetch: only this batch's contacts
 *    can ever be relevant).
 *  - Query filters on MailingCountry (null or IN :oldCountries) so the
 *    database, not Apex, discards the irrelevant rows.
 *  - Results aggregated into Map<Id, List<Contact>> with zero SOQL/DML in loops.
 *  - ONE DML statement for all candidate contacts.
 */
public inherited sharing class AccountCountrySync {

    /**
     * Entry point called from the Account after-update trigger.
     *
     * @param newAccounts   Trigger.new
     * @param oldMap        Trigger.oldMap — source of the previous BillingCountry
     */
    public static void syncMailingCountryOnBillingCountryChange(
        List<Account> newAccounts,
        Map<Id, Account> oldMap
    ) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        // ---- Pass 1 (collections only, no SOQL/DML in loops) -------------------
        // IDs of accounts in this batch whose BillingCountry actually changed,
        // plus the previous country per changed account.
        Set<Id> changedAccountIds = new Set<Id>();
        Map<Id, String> oldCountryByAccountId = new Map<Id, String>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldMap.get(acc.Id);
            String newCountry = acc.BillingCountry;
            String oldCountry = (oldAcc != null) ? oldAcc.BillingCountry : null;

            // Case-insensitive compare: 'DE' -> 'de' should count as a change
            // for our purposes? For country sync it should not — same country,
            // different formatting. Use equalsIgnoreCase so formatting-only
            // edits do not fire a pointless sync.
            Boolean changed =
                !(newCountry == null && oldCountry == null) &&
                (newCountry == null ||
                 oldCountry == null ||
                 !newCountry.equalsIgnoreCase(oldCountry));

            if (changed) {
                changedAccountIds.add(acc.Id);
                oldCountryByAccountId.put(acc.Id, oldCountry);
            }
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        // ---- ONE query for the whole batch, once, outside all loops ------------
        // Only pull contacts that could possibly be candidates: those whose
        // MailingCountry is blank or equal to one of the previous BillingCountries.
        // Everything else (contacts "working abroad") is excluded in the DB.
        List<Contact> candidates = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
              AND (MailingCountry = null OR MailingCountry IN :oldCountryByAccountId.values())
        ];

        // Aggregate contacts per account in a single pass.
        Map<Id, List<Contact>> contactsByAccountId = new Map<Id, List<Contact>>();
        for (Contact c : candidates) {
            if (!contactsByAccountId.containsKey(c.AccountId)) {
                contactsByAccountId.put(c.AccountId, new List<Contact>());
            }
            contactsByAccountId.get(c.AccountId).add(c);
        }

        // ---- Build updates (no SOQL/DML inside the loop) -----------------------
        List<Contact> toUpdate = new List<Contact>();

        for (Id accId : changedAccountIds) {
            List<Contact> accContacts = contactsByAccountId.get(accId);
            if (accContacts == null) {
                continue; // account has no (candidate) contacts
            }

            String newCountry = null;
            // Trigger.new list is ordered; recover this account's new country.
            for (Account acc : newAccounts) {
                if (acc.Id == accId) {
                    newCountry = acc.BillingCountry;
                    break;
                }
            }
            String oldCountry = oldCountryByAccountId.get(accId);

            for (Contact c : accContacts) {
                String mail = c.MailingCountry;
                Boolean eligible =
                    (mail == null) ||
                    (oldCountry != null && mail.equalsIgnoreCase(oldCountry));

                if (eligible) {
                    Contact upd = new Contact(Id = c.Id);
                    upd.MailingCountry = newCountry;
                    toUpdate.add(upd);
                }
                // else: contact lives in a different country — leave untouched.
            }
        }

        // ---- ONE DML for the whole batch ---------------------------------------
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
```

