import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    contacts = [];
    errorMessage = '';
    hasResults = false;

    requestSequence = 0;
    debounceTimerId;
    isRendered = false;

    renderedCallback() {
        // Track removal from the DOM so pending work can be cancelled.
        this.isRendered = true;
    }

    disconnectedCallback() {
        this.isRendered = false;
        this.clearDebounceTimer();
        // Invalidate any in-flight request; its response will be ignored.
        this.requestSequence++;
    }

    handleSearchChange(event) {
        this.searchTerm = event.target.value;
        this.clearDebounceTimer();

        const trimmed = (this.searchTerm || '').trim();

        if (trimmed.length < MIN_SEARCH_LENGTH) {
            this.clearResults();
            return;
        }

        // Debounce: only search once typing has paused for 300 ms.
        this.debounceTimerId = setTimeout(() => {
            this.debounceTimerId = undefined;
            this.executeSearch(trimmed);
        }, DEBOUNCE_DELAY_MS);
    }

    executeSearch(trimmedSearchTerm) {
        if (!this.isRendered) {
            return;
        }

        const sequence = ++this.requestSequence;

        searchContacts({ searchTerm: trimmedSearchTerm })
            .then((result) => {
                // Ignore stale responses and responses after disconnect.
                if (!this.isRendered || sequence !== this.requestSequence) {
                    return;
                }
                this.errorMessage = '';
                this.contacts = result || [];
                this.hasResults = true;
            })
            .catch((error) => {
                if (!this.isRendered || sequence !== this.requestSequence) {
                    return;
                }
                this.clearResults();
                this.errorMessage =
                    (error && error.body && error.body.message) ||
                    'An unknown error occurred.';
            });
    }

    clearResults() {
        this.contacts = [];
        this.hasResults = false;
        this.errorMessage = '';
    }

    clearDebounceTimer() {
        if (this.debounceTimerId !== undefined) {
            clearTimeout(this.debounceTimerId);
            this.debounceTimerId = undefined;
        }
    }

    get showResults() {
        return this.hasResults && this.contacts.length > 0;
    }
}
