import { LightningElement, api, track } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import LightningConfirm from 'lightning/confirm';
import { deleteRecord } from 'lightning/uiRecordApi';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name' },
    { label: 'Stage', fieldName: 'StageName' },
    { label: 'Amount', fieldName: 'Amount', type: 'currency' },
    {
        type: 'action',
        typeAttributes: {
            rowActions: [
                { label: 'View', name: 'view' },
                { label: 'Edit', name: 'edit' },
                { label: 'Delete', name: 'delete' },
            ],
        },
    },
];

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    @api opportunities = [];

    columns = COLUMNS;

    @track rows = [];

    connectedCallback() {
        this.rows = this.opportunities;
    }

    // Support the parent passing a new opportunities array later.
    @api
    set incomingOpportunities(value) {
        this.rows = value;
    }

    handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this.navigateToRecord(row.Id, 'view');
                break;
            case 'edit':
                this.navigateToRecord(row.Id, 'edit');
                break;
            case 'delete':
                this.confirmAndDelete(row);
                break;
            default:
                break;
        }
    }

    navigateToRecord(recordId, actionName) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId,
                objectApiName: 'Opportunity',
                actionName,
            },
        });
    }

    async confirmAndDelete(row) {
        const result = await LightningConfirm.open({
            message: `Delete opportunity "${row.Name}"? This cannot be undone.`,
            variant: 'header',
            theme: 'warning',
            label: 'Delete Opportunity',
        });

        if (!result) {
            // User cancelled — do nothing.
            return;
        }

        try {
            await deleteRecord(row.Id);
            // Do not mutate the parent's array; create a new one without the deleted row.
            this.rows = this.rows.filter((r) => r.Id !== row.Id);
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Opportunity deleted',
                    message: `"${row.Name}" was deleted successfully.`,
                    variant: 'success',
                }),
            );
        } catch (error) {
            // Keep the row in the table on failure.
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Delete failed',
                    message: error?.body?.message || 'An unknown error occurred.',
                    variant: 'error',
                }),
            );
        }
    }
}
