import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity } */
    @api lines = [];

    showError = false;

    /** Collects the editor components in display order. */
    get editors() {
        return Array.from(
            this.template.querySelectorAll('c-line-item-editor')
        );
    }

    handleReset() {
        this.editors.forEach((editor) => editor.reset());
        this.showError = false;
    }

    handleSubmit() {
        // Validate every editor so all invalid lines show their errors at once.
        const allValid = this.editors.reduce(
            (isValid, editor) => editor.validate() && isValid,
            true
        );

        if (!allValid) {
            this.showError = true;
            return;
        }

        this.showError = false;
        this.dispatchEvent(
            new CustomEvent('submit', {
                detail: {
                    lines: this.editors.map((editor) => editor.getValue())
                }
            })
        );
    }
}
