        return this._tasks;
    }
    set tasks(value) {
        this._tasks = value || [];
        this.items = this._tasks.map((task) => ({ ...task }));
    }

    connectedCallback() {
        if (this.tasks) {
            this.items = this.tasks.map((task) => ({ ...task }));
        }
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    get displayHeading() {
        return this.heading ? this.heading.toUpperCase() : '';
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }
        const task = { id: `new-${this.nextId++}`, label, done: false };
        this.items = [...this.items, task];
        this.newLabel = '';
        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label },
                bubbles: true,
                composed: true
            })
        );
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map((task) =>
            task.id === id ? { ...task, done: !task.done } : task
        );
    }
}
