public inherited sharing class EmployerService {

    private static final String ROLE_EMPLOYER = 'Current Employer';
    private static final String STATUS_CURRENT = 'Current';
    private static final String STATUS_FORMER = 'Former';
    private static final Date TODAY = Date.today();

    /**
     * Sets each contact's current employer using NPSP's standard mechanism.
     *
     * - Creates/updates a Current, primary npe5__Affiliation__c between the contact
     *   and the Organization account.
     * - Ends (Former, non-primary, EndDate = today) any previous primary affiliation
     *   with an Organization role, which is what NPSP's standard mechanism does.
     * - Contacts remain in their household accounts (nothing about Household is touched).
     *
     * Limits: 2 SOQL queries, 2 DML statements.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Normalize: skip invalid keys/values up front.
        Set<Id> contactIds = new Set<Id>();
        Set<Id> accountIds = new Set<Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id accountId = employerByContactId.get(contactId);
            if (contactId == null || accountId == null) {
                continue;
            }
            contactIds.add(contactId);
            accountIds.add(accountId);
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // Query 1: contacts and their current primary affiliation orgs.
        Map<Id, Contact> contactsById = new Map<Id, Contact>(
            [SELECT Id, npsp__Primary_Affiliation__c
             FROM Contact
             WHERE Id IN :contactIds]
        );

        // Query 2: existing affiliations for those contacts to the target orgs.
        List<npe5__Affiliation__c> existingAffiliations = [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c,
                   npe5__Primary__c, npe5__StartDate__c, npe5__EndDate__c, npe5__Role__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
              AND npe5__Organization__c IN :accountIds
        ];

        // Index existing affiliations by (contactId, orgId).
        Map<Id, npe5__Affiliation__c> existingByContactOrg = new Map<Id, npe5__Affiliation__c>();
        for (npe5__Affiliation__c aff : existingAffiliations) {
            existingByContactOrg.put(
                String.valueOf(aff.npe5__Contact__c) + '-' + String.valueOf(aff.npe5__Organization__c),
                aff
            );
        }

        List<npe5__Affiliation__c> toInsert = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> toUpdate = new List<npe5__Affiliation__c>();

        for (Id contactId : contactIds) {
            Id orgId = employerByContactId.get(contactId);
            if (orgId == null || !contactsById.containsKey(contactId)) {
                continue;
            }

            String key = String.valueOf(contactId) + '-' + String.valueOf(orgId);
            npe5__Affiliation__c existing = existingByContactOrg.get(key);

            if (existing != null) {
                // An affiliation already exists between this contact and this org.
                if (existing.npe5__Status__c == STATUS_CURRENT && existing.npe5__Primary__c) {
                    // Already the current, primary affiliation: nothing to do.
                    continue;
                }
                // Demote to Former if it was Current (or leave Former as-is),
                // but only make it primary/current if it is not already.
                if (existing.npe5__Status__c == STATUS_CURRENT && !existing.npe5__Primary__c) {
                    // A Current non-primary affiliation to the target org: promote it.
                    existing.npe5__Primary__c = true;
                    toUpdate.add(existing);
                }
                // If it is Former, NPSP will handle reactivation via the primary
                // affiliation mechanism; create a fresh Current primary affiliation.
                if (existing.npe5__Status__c == STATUS_FORMER) {
                    // Leave the Former record alone; create a new Current primary one.
                    npe5__Affiliation__c newAff = new npe5__Affiliation__c(
                        npe5__Contact__c = contactId,
                        npe5__Organization__c = orgId,
                        npe5__Status__c = STATUS_CURRENT,
                        npe5__Primary__c = true,
                        npe5__StartDate__c = TODAY,
                        npe5__Role__c = ROLE_EMPLOYER
                    );
                    toInsert.add(newAff);
                }
                continue;
            }

            // No existing affiliation to this org: create a new Current primary one.
            npe5__Affiliation__c newAff = new npe5__Affiliation__c(
                npe5__Contact__c = contactId,
                npe5__Organization__c = orgId,
                npe5__Status__c = STATUS_CURRENT,
                npe5__Primary__c = true,
                npe5__StartDate__c = TODAY,
                npe5__Role__c = ROLE_EMPLOYER
            );
            toInsert.add(newAff);
        }

        // NPSP's standard mechanism: when an affiliation becomes the primary Current
        // affiliation, NPSP updates Contact.npsp__Primary_Affiliation__c automatically,
        // and ends (Former, EndDate = today) any previous primary Current affiliation.
        // We trigger this by creating/updating the primary Current affiliation records.
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
