public class GiftImportService {
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Capture any exception from the NPSP batch invocation separately.
        Exception batchException = null;

        List<npsp__Data_Import_Settings__c> settings =
            npsp__Data_Import_Settings__c.getAll();

        List<npsp__DataImport__c> imports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c = gift.firstName;
            di.npsp__Contact1_Lastname__c = gift.lastName;
            di.npsp__Contact1_Personal_Email__c = gift.email;
            di.npsp__Donation_Amount__c = gift.amount;
            di.npsp__Donation_Date__c = gift.giftDate;
            di.npsp__Donation_Donor__c = 'Contact1';
            imports.add(di);
        }
        insert imports;

        try {
            // NPSP's supported Apex entry point: runs the BDI engine
            // synchronously, in this transaction, using the Data Import
            // settings currently configured in the org.
            npsp.BDI_Batch_DataImport_API.batchImport(
                imports,
                settings,
                settings,
                null
            );
        } catch (Exception e) {
            batchException = e;
        }

        Integer i = 0;
        for (npsp__DataImport__c di : imports) {
            ImportResult result = new ImportResult();
            Boolean imported = (di.npsp__Status__c == 'Imported');
            if (batchException != null) {
                result.success = false;
                result.errorMessage = batchException.getMessage();
            } else if (imported) {
                result.success = true;
                result.contactId = (Id) di.get('npsp__Contact1Imported__c');
                result.opportunityId = (Id) di.get('npsp__DonationImported__c');
            } else {
                result.success = false;
                result.errorMessage = di.npsp__FailureInformation__c;
            }
            results.add(result);
            i++;
        }
        return results;
    }
}
