public class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    // Picklist value used by Enhanced Recurring Donations for monthly periods.
    private static final String MONTHLY_PERIOD = 'Monthly';
    // NPSP status value for an active recurring donation.
    private static final String STATUS_ACTIVE = 'Active';

    /**
     * Creates one Enhanced Recurring Donation per request and returns the new Ids
     * in request order. Validates all requests before any DML so a bad batch
     * never partially commits. Uses exactly one SOQL query and one DML statement
     * regardless of request count.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // ---- Full-batch validation before any DML -------------------------------
        List<String> errors = new List<String>();
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest req = requests[i];
            Integer reqNum = i + 1;
            if (req == null) {
                errors.add('Request ' + reqNum + ': request cannot be null.');
                continue;
            }
            if (req.contactId == null) {
                errors.add('Request ' + reqNum + ': contactId is required.');
            }
            if (req.amount == null || req.amount <= 0) {
                errors.add('Request ' + reqNum
                    + ': amount must be a positive number.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                errors.add('Request ' + reqNum
                    + ': dayOfMonth must be between 1 and 31.');
            }
            if (req.startDate == null) {
                errors.add('Request ' + reqNum + ': startDate is required.');
            }
        }
        if (!errors.isEmpty()) {
            throw new RecurringGiftException(String.join(errors, ' | '));
        }

        // ---- Build one record per request ---------------------------------------
        // No SOQL and no DML in this loop; only field assignments.
        List<npe03__Recurring_Donation__c> donations =
            new List<npe03__Recurring_Donation__c>();
        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();

            // Donor: this service always creates individual (contact-based)
            // recurring gifts, so only the contact lookup is populated.
            rd.npe03__Contact__c = req.contactId;

            // Each installment is `amount`; leave the double-defaulted Total
            // Amount (npe03__Amount__c) to NPSP's rollup so it does not override
            // the per-installment value.
            rd.npe03__Amount__c = req.amount;

            // Fixed-length vs open-ended schedule.
            if (req.installments == null || req.installments == 0) {
                rd.npe03__Installments__c = null;
                rd.npe03__Open_Ended_Status__c = 'Open';
                rd.npsp__EndDate__c = null;
            } else {
                rd.npe03__Installments__c = req.installments;
                rd.npe03__Open_Ended_Status__c = null;
            }

            rd.npe03__Installment_Period__c = MONTHLY_PERIOD;
            rd.npe03__Schedule_Type__c = 'Custom';
            rd.npsp__RecurringType__c = 'Fixed'; // every month on the same day
            rd.npsp__InstallmentFrequency__c = 1; // once per month

            // Day-of-month handling: the form's "31" means "last day of the
            // month". Enhanced Recurring Donations stores that as the
            // Always_Use_Last_Day_Of_Month option rather than day 31, so that a
            // schedule starting on a 28/29/30-day month still lands on the last
            // day of each month.
            if (req.dayOfMonth == 31) {
                rd.npsp__Day_of_Month__c = null;
                rd.npsp__Always_Use_Last_Day_Of_Month__c = true;
            } else {
                rd.npsp__Day_of_Month__c = req.dayOfMonth;
                rd.npsp__Always_Use_Last_Day_Of_Month__c = false;
            }

            rd.npsp__StartDate__c = req.startDate;
            rd.npe03__Date_Established__c = req.startDate;
            rd.npe03__Next_Payment_Date__c = firstPaymentDate(req);
            if (req.installments != null && req.installments > 0) {
                rd.npsp__EndDate__c = lastPaymentDate(req);
            } else {
                rd.npsp__EndDate__c = null;
            }

            rd.npsp__Status__c = STATUS_ACTIVE;
            rd.npsp__PaymentMethod__c = req.paymentMethod;

            donations.add(rd);
        }

        // ---- Exactly one DML statement ------------------------------------------
        // NPSP's Enhanced Recurring Donation trigger builds the installment
        // opportunities, so this service must not create Opportunities itself.
        insert donations;

        List<Id> result = new List<Id>();
        for (npe03__Recurring_Donation__c rd : donations) {
            result.add(rd.Id);
        }
        return result;
    }

    // Computes the first installment date in Apex instead of querying the
    // payments-related objects, keeping this method within the 1-SOQL budget.
    private static Date firstPaymentDate(GiftRequest req) {
        Date d = req.startDate;
        if (req.dayOfMonth == 31) {
            return lastDayOfMonth(d);
        }
        Integer daysInMonth = daysInMonthOf(d);
        // If the chosen day does not exist in the start month (e.g. Jan 31
        // schedule starting in a 28-day February), the first payment falls in
        // the following month.
        if (req.dayOfMonth > daysInMonth) {
            d = d.addMonths(1);
            return resolveDay(d.year(), d.month(), req.dayOfMonth);
        }
        return Date.newInstance(d.year(), d.month(), req.dayOfMonth);
    }

    private static Date lastPaymentDate(GiftRequest req) {
        Date first = firstPaymentDate(req);
        Date last = first.addMonths(req.installments - 1);
        if (req.dayOfMonth == 31) {
            return lastDayOfMonth(last);
        }
        return resolveDay(last.year(), last.month(), req.dayOfMonth);
    }

    private static Date lastDayOfMonth(Date d) {
        Integer dim = daysInMonthOf(d);
        return Date.newInstance(d.year(), d.month(), dim);
    }

    private static Integer daysInMonthOf(Date d) {
        return Date.daysInMonth(d.year(), d.month());
    }

    // Clamps days that do not exist in a month (e.g. 30 in February) to the last
    // day of that month. 29 and 30 remain as themselves whenever the month has
    // them, matching the "29 and 30 are stored as those days" rule.
    private static Date resolveDay(Integer year, Integer month, Integer day) {
        Integer dim = Date.daysInMonth(year, month);
        return Date.newInstance(year, month, day > dim ? dim : day);
    }
