            }
            if (percent <= 0) {
                throw new AllocationException('Percentage for General Accounting Unit ' + gauId + ' must be greater than 0.');
            }
            percent = percent.setScale(percentScale, RoundingMode.HALF_UP);
            normalizedPercentByGauId.put(gauId, percent);
            totalPercent += percent;
