/**
 * @description Service for replacing the NPSP GAU Allocations of an Opportunity
 *              with percentage-based allocations across one or more General
 *              Accounting Units.
 *
 *              Percentages are persisted on npsp__Percent__c in addition to
 *              npsp__Amount__c. NPSP recalculates the Amount of percent-based
 *              GAU Allocations whenever the related Opportunity's Amount
 *              changes, so allocations created by this service stay correct
 *              (e.g. a $1,000 gift split 60/40 corrected to $2,000 yields
 *              $1,200 and $800) with no further intervention.
 *
 *              All validation happens before any data is modified; either the
 *              full replace succeeds or an AllocationException is thrown and
 *              the transaction is left untouched.
 */
public with sharing class GauAllocationService {

    /** Thrown when the requested allocation cannot be performed. */
    public class AllocationException extends Exception {}

    /** Currency scale used when computing npsp__Amount__c. */
    private static final Integer AMOUNT_SCALE = 2;

    /** Maximum allowed combined percentage (a total below 100% is allowed). */
    private static final Decimal TOTAL_PERCENT_LIMIT = 100;

    /**
     * @description Replaces all existing GAU Allocations of the given
     *              Opportunity with one allocation per map entry.
     * @param opportunityId   Id of the Opportunity to allocate.
     * @param percentByGauId  Map of npsp__General_Accounting_Unit__c Id to
     *                        percentage (60 means 60%). The total may be at
     *                        most 100; anything below 100 simply remains
     *                        unallocated.
     * @return The inserted npsp__Allocation__c records.
     * @throws GauAllocationService.AllocationException if the map is null or
     *         empty, any percentage is null or not greater than 0, the
     *         percentages add up to more than 100, the Opportunity does not
     *         exist, or any referenced GAU does not exist or is inactive.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // ------------------------------------------------------------------
        // Validation phase - no data is changed until every check has passed.
        // ------------------------------------------------------------------
        if (opportunityId == null) {
            throw new AllocationException('opportunityId must not be null.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('percentByGauId must contain at least one GAU percentage.');
        }

        // Normalize each percentage to the scale of the npsp__Percent__c field
        // so the stored percent always matches the amount computed from it,
        // then validate the individual percentages and their total.
        Integer percentScale = npsp__Allocation__c.npsp__Percent__c.getDescribe().getScale();
        Map<Id, Decimal> normalizedPercentByGauId = new Map<Id, Decimal>();
        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null) {
                throw new AllocationException(
                    'Percentage for General Accounting Unit ' + gauId + ' must not be null.');
            }
            if (percent <= 0) {
                throw new AllocationException(
                    'Percentage for General Accounting Unit ' + gauId + ' must be greater than 0.');
            }
            percent = percent.setScale(percentScale, RoundingMode.HALF_UP);
            normalizedPercentByGauId.put(gauId, percent);
            totalPercent += percent;
        }
        if (totalPercent > TOTAL_PERCENT_LIMIT) {
            throw new AllocationException(
                'Percentages must not add up to more than 100 (total was ' + totalPercent + ').');
        }

        // The Opportunity must exist; its Amount (when set) drives the amounts.
        Opportunity opportunity = [
            SELECT Id, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];
        if (opportunity == null) {
            throw new AllocationException('Opportunity ' + opportunityId + ' does not exist.');
        }

        // Every referenced GAU must exist and be active.
        Map<Id, npsp__General_Accounting_Unit__c> gausById = new Map<Id, npsp__General_Accounting_Unit__c>([
            SELECT Id, Name, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :normalizedPercentByGauId.keySet()
        ]);
        for (Id gauId : normalizedPercentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau == null) {
                throw new AllocationException(
                    'General Accounting Unit ' + gauId + ' does not exist.');
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException(
                    'General Accounting Unit "' + gau.Name + '" (' + gauId + ') is inactive.');
            }
        }

        // ------------------------------------------------------------------
        // Data changes - all validation has passed at this point.
        // ------------------------------------------------------------------

        // Replace: remove every existing allocation of this Opportunity.
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        // Build one allocation per map entry. npsp__Percent__c is persisted so
        // NPSP keeps each allocation's Amount in sync if the Opportunity amount
        // changes later; npsp__Amount__c is set now so the allocations are
        // correct immediately (and remain correct even when Amount is null).
        List<Id> orderedGauIds = new List<Id>(normalizedPercentByGauId.keySet());
        orderedGauIds.sort(); // deterministic insert order and return order

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : orderedGauIds) {
            Decimal percent = normalizedPercentByGauId.get(gauId);
            npsp__Allocation__c allocation = new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percent
            );
            if (opportunity.Amount != null) {
                allocation.npsp__Amount__c =
                    (opportunity.Amount * percent / 100).setScale(AMOUNT_SCALE, RoundingMode.HALF_UP);
            }
            newAllocations.add(allocation);
        }

        insert newAllocations;
        return newAllocations;
    }
}
