/**
 * @description Creates a single new NPSP Household Account for a list of new
 * Contacts, in one transaction, and returns the Id of that household.
 *
 * Key points:
 *  - Only ONE Account is inserted (the NPSP Household Account). Contacts are
 *    linked to it via AccountId, so no extra/empty households are created
 *    (NPSP's contact account-creation triggers are satisfied by the explicit
 *    AccountId, and we never insert contacts without one).
 *  - The household is created with the Household Account record type looked
 *    up by DeveloperName ('HH_Account') -- never hard-coded Ids.
 *  - The account Name is NOT set here: NPSP's household naming trigger names
 *    the household and generates greetings. We only pass the record type and
 *    primary contact.
 *  - The first contact in the list becomes the household's primary contact
 *    via Account.npe01__One2OneContact__c.
 *  - All DML is bulkified (single account insert, single contacts insert) and
 *    runs after NPSP's own triggers have done their household processing.
 */
public inherited sharing class HouseholdService {

    /** DeveloperName of the NPSP Household Account record type in this org. */
    @TestVisible
    private static final String HOUSEHOLD_RECORD_TYPE_DEV_NAME = 'HH_Account';

    /** API name of the field NPSP uses to store a household's primary contact. */
    @TestVisible
    private static final String ONE_TO_ONE_CONTACT_FIELD = 'npe01__One2OneContact__c';

    /**
     * @description Creates one new NPSP Household Account and inserts all the
     *              given (new, unsaved) Contacts as its members.
     * @param members New Contacts to place in the household. Must be non-null
     *                and non-empty; none of them may already have an Id.
     * @return The Id of the newly created household Account.
     * @throws IllegalArgumentException if members is null, empty, contains a
     *         saved Contact, or more than 200 members are supplied.
     */
    public static Id createHousehold(List<Contact> members) {
        validate(members);

        Account household = buildHouseholdAccount(members);

        insert household; // single row; NPSP triggers handle naming/greetings

        List<Contact> toInsert = prepareMembers(members, household.Id);
        insert toInsert; // bulk-safe for up to the row limit

        return household.Id;
    }

    /**
     * @description Validates the input list before doing any DML.
     */
    private static void validate(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'HouseholdService.createHousehold requires a non-empty list of Contacts.'
            );
        }
        // Guard against anyone passing already-saved contacts, which would
        // leave them in their existing (possibly auto-created) households and
        // break the "one new household" guarantee.
        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException(
                    'HouseholdService.createHousehold received a null Contact in the list.'
                );
            }
            if (member.Id != null) {
                throw new IllegalArgumentException(
                    'Contacts passed to HouseholdService.createHousehold must be new (no Id).'
                );
            }
        }
        if (members.size() > Limits.getLimitDmlRows()) {
            throw new IllegalArgumentException(
                'Too many household members for a single transaction.'
            );
        }
    }

    /**
     * @description Builds the new household Account. Only the record type and
     *              primary contact are supplied so NPSP's household naming and
     *              greeting logic runs untouched.
     */
    private static Account buildHouseholdAccount(List<Contact> members) {
        Id householdRtId = Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName()
            .get(HOUSEHOLD_RECORD_TYPE_DEV_NAME).getRecordTypeId();

        Account household = new Account(
            // No Name: NPSP names the household and generates greetings.
            RecordTypeId = householdRtId
        );

        // First contact in the list is the household's primary contact.
        // NPSP copies this onto the account's One-to-One field.
        household.put(ONE_TO_ONE_CONTACT_FIELD, null); // field must exist; value set after contact insert

        return household;
    }

    /**
     * @description Stages the Contacts for insert, each pointed at the new
     *              household Account so no additional accounts are created.
     */
    private static List<Contact> prepareMembers(List<Contact> members, Id householdId) {
        List<Contact> toInsert = new List<Contact>();
        for (Contact member : members) {
            // Work on a shallow copy so we do not mutate the caller's list.
            Contact c = new Contact(
                FirstName = member.FirstName,
                LastName  = member.LastName,
                Email     = member.Email,
                Phone     = member.Phone,
                AccountId = householdId
            );
            toInsert.add(c);
        }
        return toInsert;
    }
}
