        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    private static final String PSC_OBJECT = 'npsp__Partial_Soft_Credit__c';
    private static final String HOUSEHOLD_MEMBER_ROLE = 'Household Member';

    /**
     * Adds or updates NPSP partial soft credits for the given (opportunity, contact) pairs.
     *
     * Guarantees:
     *  - All-or-nothing validation before any DML: if any request is invalid
     *    (primary contact, null/non-positive/oversized amount), a SoftCreditException
     *    is thrown and no records are modified.
     *  - Each request's contact ends up with exactly one partial soft credit on the
     *    opportunity, of the requested amount and role, linked to that contact's
     *    OpportunityContactRole whose Role equals the requested role. If the contact
     *    already had a role on the opportunity (e.g. NPSP's "Household Member"), that
     *    existing role is repurposed (Role set to the requested role); otherwise a new
     *    OpportunityContactRole is created.
     *  - If the contact already has a partial soft credit on the opportunity, its
     *    amount and role are updated instead of inserting a duplicate.
     *  - Null or empty input is a no-op.
     *  - Uses at most 4 SOQL queries and 4 DML statements regardless of request count.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ---- Step 0: sanity-normalize requests ------------------------------------
        // Requests never repeat the same opportunity/contact pair (per contract),
        // but we still guard against duplicates defensively by de-duping.
        Map<Id, Map<Id, SoftCreditRequest>> byOppContact = new Map<Id, Map<Id, SoftCreditRequest>>();
        for (SoftCreditRequest req : requests) {
            if (req == null || req.opportunityId == null || req.contactId == null) {
                continue;
            }
            if (!byOppContact.containsKey(req.opportunityId)) {
                byOppContact.put(req.opportunityId, new Map<Id, SoftCreditRequest>());
            }
            byOppContact.get(req.opportunityId).put(req.contactId, req);
        }
        if (byOppContact.isEmpty()) {
            return;
        }

        // ---- SOQL #1: opportunities (amount, primary contact) ---------------------
        Set<Id> oppIds = byOppContact.keySet();
        Map<Id, Opportunity> oppsById = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity
             WHERE Id IN :oppIds]
        );

        // ---- Validation: entire call validated before any DML ---------------------
        List<String> errors = new List<String>();
        for (Id oppId : byOppContact.keySet()) {
            Opportunity opp = oppsById.get(oppId);
            for (SoftCreditRequest req : byOppContact.get(oppId).values()) {
                String label = 'Opportunity ' + oppId + ' / Contact ' + req.contactId + ': ';

                if (opp == null) {
                    errors.add(label + 'Opportunity not found.');
                    continue;
                }
                if (opp.npsp__Primary_Contact__c == req.contactId) {
                    errors.add(label + 'Contact is the opportunity\'s primary contact and cannot receive a partial soft credit.');
                }
                if (req.amount == null) {
                    errors.add(label + 'Amount must not be null.');
                } else if (req.amount <= 0) {
                    errors.add(label + 'Amount must be positive.');
                } else if (opp.Amount == null || req.amount > opp.Amount) {
                    errors.add(label + 'Amount must not exceed the opportunity amount.');
                }
            }
        }
        if (!errors.isEmpty()) {
            throw new SoftCreditException(String.join(errors, ' | '));
        }

        // ---- SOQL #2: existing contact roles for the requested contacts -----------
        // We need, per (opportunity, contact), the contact's OpportunityContactRole
        // (any role, incl. "Household Member"), and separately whether a role with the
        // requested role already exists.
        List<OpportunityContactRole> existingRoles = [
            SELECT Id, OpportunityId, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
              AND ContactId IN :contactIdsFrom(byOppContact)
        ];
        Map<Id, Map<Id, OpportunityContactRole>> rolesByOppContact = new Map<Id, Map<Id, OpportunityContactRole>>();
        for (OpportunityContactRole ocr : existingRoles) {
            if (!rolesByOppContact.containsKey(ocr.OpportunityId)) {
                rolesByOppContact.put(ocr.OpportunityId, new Map<Id, OpportunityContactRole>());
            }
            // Defensive: keep first per pair; contract says contact ends with exactly one role.
            if (!rolesByOppContact.get(ocr.OpportunityId).containsKey(ocr.ContactId)) {
                rolesByOppContact.get(ocr.OpportunityId).put(ocr.ContactId, ocr);
            }
        }

        // ---- Plan contact role changes --------------------------------------------
        // For each request, target role record:
        //  - existing role for that pair -> repurpose it (update Role), preserving IsPrimary
        //    unless the requested role is "Household Member" (never primary);
        //  - none -> insert new role (never primary for household role).
        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> roleIdByPairKey = new Map<String, OpportunityContactRole>();

        for (Id oppId : byOppContact.keySet()) {
            for (SoftCreditRequest req : byOppContact.get(oppId).values()) {
                OpportunityContactRole existing = rolesByOppContact.containsKey(oppId)
                    ? rolesByOppContact.get(oppId).get(req.contactId)
                    : null;
