                    roleIdByPairKey.put(pairKey(oppId, req.contactId), existing);
                } else {
                    OpportunityContactRole newRole = new OpportunityContactRole(
                        OpportunityId = oppId,
                        ContactId = req.contactId,
                        Role = req.role,
                        IsPrimary = false
                    );
                    rolesToInsert.add(newRole);
                    roleIdByPairKey.put(pairKey(oppId, req.contactId), newRole);
                }
            }
        }

