public class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    /**
     * Converts an open pledge (Opportunity) into a monthly installment plan.
     *
     * - Existing payments that are Paid or Written Off are considered history and are untouched.
     * - All other payments (unpaid and not written off) are deleted.
     * - New unpaid payments are inserted, one per month, starting at firstPaymentDate.
     *   Payment i is scheduled on firstPaymentDate.addMonths(i).
     * - Each payment amount is the outstanding amount (Opportunity Amount minus the sum of
     *   Paid + Written Off payment amounts) divided by numberOfPayments, rounded DOWN to the
     *   cent. The last payment absorbs any remainder so payments sum exactly to the outstanding
     *   amount.
     *
     * @param opportunityId    the pledge to reschedule
     * @param numberOfPayments  number of new installment payments (must be >= 1)
     * @param firstPaymentDate  scheduled date of the first installment
     * @return the inserted payments in schedule order (earliest first)
     * @throws PaymentPlanException if inputs are invalid, the opportunity is closed, or the
     *                              outstanding amount is not greater than zero. Nothing is changed.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {
        // ---------- Validation (nothing is modified before this passes) ----------
        if (opportunityId == null) {
            throw new PaymentPlanException('Opportunity Id is required.');
        }
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('Number of payments must be provided and be at least 1.');
        }

        // Amount per installment is rounded to the cent, so numberOfPayments is naturally capped
        // by the outstanding cents; validate proportionally after we know the outstanding amount.
        // A hard governor-friendly cap guards against absurd values (e.g., Integer.MAX_VALUE),
        // which would explode the loop/insert even if the arithmetic survived.
        if (numberOfPayments > 1000) {
            throw new PaymentPlanException('Number of payments must be 1000 or fewer.');
        }

        Opportunity opp = [
            SELECT Id, Name, Amount, IsClosed, StageName
            FROM Opportunity
            WHERE Id = :opportunityId
        ];
        if (opp == null) {
            throw new PaymentPlanException('Opportunity not found: ' + opportunityId);
        }
        if (opp.isClosed) {
            throw new PaymentPlanException('Opportunity ' + opp.Name + ' is closed and cannot be rescheduled.');
        }

        // History = paid or written-off payments; these stay and reduce the outstanding amount.
        List<npe01__OppPayment__c> historyPayments = [
            SELECT Id, npe01__Payment_Amount__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
              AND (npe01__Paid__c = true OR npe01__Written_Off__c = true)
        ];

        // Everything else (unpaid and not written off) is replaced by the new schedule.
        List<npe01__OppPayment__c> replaceablePayments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
              AND npe01__Paid__c = false
              AND npe01__Written_Off__c = false
        ];

        // ---------- Compute amounts (Decimal arithmetic, currency-aware) ----------
        Decimal opportunityAmount = opp.Amount == null ? 0 : opp.Amount;
        Decimal paidOrWrittenOff = 0;
        for (npe01__OppPayment__c p : historyPayments) {
            if (p.npe01__Payment_Amount__c != null) {
                paidOrWrittenOff += p.npe01__Payment_Amount__c;
            }
        }
        Decimal outstanding = opportunityAmount - paidOrWrittenOff;
        if (outstanding <= 0) {
            throw new PaymentPlanException(
                'Outstanding amount must be greater than zero for Opportunity ' + opp.Name + '.'
            );
        }

        // ---------- Build the new payment schedule (not persisted yet) ----------
        // Per-payment amount: outstanding / n, rounded DOWN to the cent.
        Decimal perPayment = (outstanding / numberOfPayments).setScale(2, RoundingMode.DOWN);

        // Number of installments cannot exceed the outstanding cents, otherwise per-payment
        // would round down to 0.00 for some payments.
        if (numberOfPayments * 100 > outstanding.movePointRight(2).setScale(0, RoundingMode.DOWN).intValue()) {
            throw new PaymentPlanException(
                'Number of payments exceeds the number of cents in the outstanding amount.'
            );
        }

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            Boolean isLast = (i == numberOfPayments - 1);
            Decimal amt = perPayment;
            if (isLast) {
                amt = outstanding - (perPayment * (numberOfPayments - 1));
            }
            newPayments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amt,
                npe01__Scheduled_Date__c = firstPaymentDate == null
                    ? Date.today().addMonths(i)
                    : firstPaymentDate.addMonths(i),
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            ));
        }

        // ---------- Persist: delete stale unpaid payments, then insert the new schedule ----------
        // DML ordering: deletes first, then insert, in one transaction. If the insert fails,
        // the transaction rolls back (all-or-nothing), satisfying "without changing anything".
        if (!replaceablePayments.isEmpty()) {
            delete replaceablePayments;
        }
        insert newPayments;

        // SObjects returned from the DML carry their Ids; return in schedule order.
        return newPayments;
    }
}
