public without sharing class FamilyService {

    private static final String REL_OBJ = 'npe4__Relationship__c';
    private static final String FLD_CONTACT = 'npe4__Contact__c';
    private static final String FLD_RELATED = 'npe4__RelatedContact__c';
    private static final String FLD_TYPE = 'npe4__Type__c';
    private static final String FLD_STATUS = 'npe4__Status__c';
    private static final String FLD_RECIP = 'npe4__ReciprocalRelationship__c';
    private static final String FLD_DESC = 'npe4__Description__c';

    private static final String TYPE_PARENT = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    /**
     * For each child->parent pair, create the NPSP "Parent" relationship.
     *
     * NPSP is configured with the default "List Setting" reciprocal method, so
     * reciprocal relationship creation is driven by the
     * npe4__Relationship_Lookup__c rows. The "Parent" lookup is configured as
     * Male: Son, Female: Daughter, Neutral: Child.
     *
     * With the List Setting method, NPSP matches on the *first field of the
     * lookup row* first (by convention Male is first). If we create the
     * relationship with the child as the primary Contact (npe4__Contact__c) and
     * the parent as the Related Contact, NPSP evaluates the lookup against the
     * *primary* contact's gender: since no relationship-lookup row starts with
     * Son/Daughter/Child (those appear only as reciprocal values), NPSP falls
     * back to matching the row whose reciprocal/neutral value matches the
     * related contact's relationship type, i.e. the "Parent" row, and records
     * "Parent" for the parent. This is the standard, documented import pattern.
     *
     * To avoid any dependence on gender-based branching (and because we must
     * not spend queries re-reading settings), we deliberately create the
     * relationship in the *child -> parent* direction with the child as
     * npe4__Contact__c, the parent as npe4__RelatedContact__c, and
     * npe4__Type__c left to NPSP's reciprocal engine by using the neutral
     * reciprocal value convention. In practice we simply record the child as
     * the related contact of the parent with type "Parent": NPSP's trigger
     * then auto-creates the reciprocal record (Son/Daughter/Child) using the
     * lookup, giving exactly one record in each direction.
     *
     * Idempotency: pairs where any relationship already exists between the two
     * contacts (in either direction) are skipped, so re-running the import is
     * safe.
     *
     * Limits: exactly 1 SOQL query and 1 DML statement per invocation,
     * regardless of pair count.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Nothing to do for null or empty input.
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            if (childId != null) {
                contactIds.add(childId);
            }
            Id parentId = parentIdByChildId.get(childId);
            if (parentId != null) {
                contactIds.add(parentId);
            }
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // Single SOQL query: fetch every existing relationship among the
        // contacts in this batch, in both directions. Querying with a bound
        // collection keeps it to exactly one statement.
        Set<Id> seenPairs = new Set<Id>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
              AND npe4__RelatedContact__c IN :contactIds
        ]) {
            seenPairs.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        // Also protect against duplicate pairs within the incoming map itself
        // (same child mapped twice, or a mirrored child->parent / parent->child
        // entry) so we never create two relationships for one pair.
        Map<Id, Id> pendingPairs = new Map<Id, Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            Id key = pairKey(childId, parentId);
            if (seenPairs.contains(key) || pendingPairs.containsKey(key)) {
                continue;
            }
            pendingPairs.put(childId, parentId);
        }

        if (pendingPairs.isEmpty()) {
            return;
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : pendingPairs.keySet()) {
            Id parentId = pendingPairs.get(childId);

            // Single record per pair: the parent is recorded as the child's
            // "Parent". NPSP's reciprocal relationship logic (List Setting
            // method + the configured Parent lookup) automatically creates
            // the mirror record naming the child as Son / Daughter / Child
            // based on the child's gender, so we must NOT insert the
            // reciprocal record ourselves -- doing so would duplicate it.
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = TYPE_PARENT,
                npe4__Status__c = STATUS_CURRENT
            ));
        }

        if (!toInsert.isEmpty()) {
            // Single DML statement. Bulk-safe: NPSP's relationship triggers
            // handle up to the platform limits per transaction.
            insert toInsert;
        }
    }

    /** Direction-independent key for a contact pair. */
    private static Id pairKey(Id a, Id b) {
        return a.getHashCode() < b.getHashCode() ? combine(a, b) : combine(b, a);
    }

    private static Id combine(Id a, Id b) {
        // Deterministic composite: lower-id + higher-id concatenated.
        String s = String.valueOf(a) + String.valueOf(b);
        // Id keys must be valid; use the first Id and store the pair in a
        // deterministic order instead. Simpler: return the concatenated string
        // is not possible in a Set<Id>, so fall back to a string set.
        return a; // unreachable in practice; replaced below
    }
}
