/**
 * TDTM Trigger Handler: OPP_MajorGiftFollowUp_TDTM
 *
 * NPSP Table-Driven Trigger Management handler for Opportunity (AfterInsert / AfterUpdate).
 * Creates one follow-up Task when an Opportunity qualifies as a major gift:
 *   - Closed Won AND Amount >= 5000
 *   - On insert, or on update when it was NOT already Closed Won with Amount >= 5000.
 *
 * Registered by the admin as an NPSP Trigger Handler record:
 *   Class = OPP_MajorGiftFollowUp_TDTM, Object = Opportunity,
 *   Trigger Action = AfterInsert;AfterUpdate, Load Order = 5, Asynchronous = false.
 * When that record is deactivated, NPSP's dispatcher stops invoking this class.
 *
 * Bulk-safe: handles 200+ records with at most 1 SOQL query and 1 DML statement of its own.
 * (TDTM's in-memory Trigger.new/Trigger.oldMap make a deduplication query unnecessary.)
 */
public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;

    /** Core qualification: Closed Won with Amount >= 5000. */
    private Boolean isMajorGift(Opportunity opp) {
        return opp.get('IsWon') == Boolean.TRUE
            && opp.get('Amount') != null
            && (Decimal) opp.get('Amount') >= MAJOR_GIFT_THRESHOLD;
    }

    /**
     * Runs from the npsp.TDTM_Runnable base when the dispatcher calls run().
     * Respects the admin's Trigger Handler toggle (npsp.TDTM_Config__c)
     * and the Opportunity-level in-memory state of the current transaction.
     */
    private Boolean shouldRun() {
        return
            npsp.TDTM_Config__c.getInstance().TriggerHandler_On__c &&
            TriggerHandler_Off__c == false &&
            !(TDTM_Global_API.getIsBlocked('Opportunity'));
    }

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        // Always call super.run() so the base class runs its own dispatcher plumbing.
        npsp.TDTM_Runnable.DmlWrapper wrap = super.run(newlist, oldlist, triggerAction, objResult);

        // The admin deactivated the Trigger Handler record: do nothing.
        if (!shouldRun()) {
            return wrap;
        }

        List<Task> tasksToCreate = new List<Task>();

        for (Integer i = 0; i < newlist.size(); i++) {
            Opportunity newOpp = (Opportunity) newlist[i];

            if (!isMajorGift(newOpp)) {
                continue; // not Closed Won >= 5000: skip
            }

            if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
                // Insert: qualifies now -> create task.
                tasksToCreate.add(buildTask(newOpp));
            } else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                Opportunity oldOpp = (Opportunity) oldlist[i];

                // "Was not both of those before": the OLD record was not already
                // Closed Won with Amount >= 5000. Editing a gift that already
                // qualified must not create another task.
                Boolean wasMajorGiftBefore =
                    oldOpp.get('IsWon') == Boolean.TRUE
                    && oldOpp.get('Amount') != null
                    && (Decimal) oldOpp.get('Amount') >= MAJOR_GIFT_THRESHOLD;

                if (!wasMajorGiftBefore) {
                    tasksToCreate.add(buildTask(newOpp));
                }
            }
        }

        if (!tasksToCreate.isEmpty()) {
            insert tasksToCreate; // 1 DML statement
        }

        return wrap;
    }

    private Task buildTask(Opportunity opp) {
        Task t = new Task(
            Subject  = 'Major gift thank-you call',
            Priority = 'High',
            Status   = 'Not Started',
            WhatId   = opp.Id
        );

        // WhoId = npsp__Primary_Contact__c when present, else fall back to OwnerId.
        Id primaryContactId = (Id) opp.get('npsp__Primary_Contact__c');
        t.OwnerId = opp.OwnerId;
        if (primaryContactId != null) {
            t.WhoId = primaryContactId;
        }

        // ActivityDate = CloseDate + 3 days.
        if (opp.get('CloseDate') != null) {
            t.ActivityDate = ((Date) opp.get('CloseDate')).addDays(3);
        }

        return t;
    }
}
