// ---------------------------------------------------------------------------
// RecordAccessService
//
// Answers the question "which of these records can the running user edit?"
// for a mass-edit screen, using the platform's own access engine
// (UserRecordAccess). A single bulk query covers object permissions,
// ownership, sharing rules, role hierarchy, View All / Modify All,
// Modify All Data, etc., exactly as the UI would evaluate them, and the
// result reflects any sharing/permission changes made earlier in the same
// transaction.
//
// Contract:
//   - editableIds(null) / editableIds(new Set<Id>()) -> empty Set (never null)
//   - Accepts up to 2,000 mixed-object Ids per call
//   - Uses at most 1 SOQL query for 2,000 Ids (budget: 20)
//   - Never mutates the caller's input set; never returns null Ids
// ---------------------------------------------------------------------------
public with sharing class RecordAccessService {

    // Max number of Ids bound into a single UserRecordAccess query.
    // The governor limit for items in an IN clause is 4,000, so 2,000 keeps
    // headroom while guaranteeing the contracted input (2,000 Ids) resolves
    // in exactly ONE SOQL call. Larger-than-contract inputs (defensive only)
    // are simply split across multiple queries rather than dropped.
    private static final Integer QUERY_CHUNK_SIZE = 2000;

    /**
     * Returns the subset of recordIds that the running user can edit
     * (UserRecordAccess.HasEditAccess == true), taking into account object
     * permissions, ownership, sharing, the role hierarchy, and
     * View All / Modify All / Modify All Data.
     *
     * Records that do not exist or are not visible to the running user
     * yield no editable row and are therefore excluded, which is the
     * correct, secure behavior for a mass-edit screen.
     *
     * @param recordIds candidate record Ids across any object; may be null,
     *                  empty, or contain null elements
     * @return the editable subset as an 18-character Id set; never null
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();

        // Null or empty input -> empty set, never null.
        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        // Sanitize and deduplicate the input: drop nulls, copy so the
        // caller's set is never mutated. Elements are already valid Apex Ids
        // (the Id type normalizes 15-char forms to 18-char on assignment),
        // so no per-Id validation is required here.
        Set<Id> sanitizedIds = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                sanitizedIds.add(recordId);
            }
        }

        if (sanitizedIds.isEmpty()) {
            return result;
        }

        // Query the platform access engine in chunks. For the contracted
        // 2,000 Ids this executes exactly one SOQL query, well within the
        // 20-query budget. UserId is filtered explicitly, which is the
        // required filter combination (UserId + RecordId) for this object.
        List<List<Id>> chunks = splitIntoChunks(sanitizedIds, QUERY_CHUNK_SIZE);

        for (List<Id> chunk : chunks) {
            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND RecordId IN :chunk
            ]) {
                // Filter again in Apex for belt-and-braces; only Ids that
                // were part of the input can appear here thanks to the
                // RecordId IN :chunk filter.
                if (access.HasEditAccess == true) {
                    result.add(access.RecordId);
                }
            }
        }

        return result;
    }

    /**
     * Splits a set of Ids into ordered chunks of at most chunkSize elements.
     * Chunking is defensive: the documented caller contract (2,000 Ids)
     * produces a single chunk / single query, but this keeps the method
     * bulk-safe and governor-compliant even if a caller over-indulges.
     *
     * @param ids       sanitized, non-null input Ids
     * @param chunkSize maximum elements per chunk (> 0)
     * @return list of chunks; never null
     */
    private static List<List<Id>> splitIntoChunks(Set<Id> ids, Integer chunkSize) {
        List<List<Id>> chunks = new List<List<Id>>();
        List<Id> currentChunk = new List<Id>();

        for (Id recordId : ids) {
            currentChunk.add(recordId);
            if (currentChunk.size() >= chunkSize) {
                chunks.add(currentChunk);
                currentChunk = new List<Id>();
            }
        }
        if (!currentChunk.isEmpty()) {
            chunks.add(currentChunk);
        }
        return chunks;
    }
}
