/**
 * TAF after insert / after update action for Opportunity.
 *
 * Collects the Ids of every Opportunity of the current DML operation that must
 * be pushed to the ERP, then hands them to the DML finalizer
 * (OpportunityErpSyncFinalizer) exactly once per DML operation.
 *
 * Trigger chunks: a 250-record DML runs the after context in chunks (200 + 50),
 * so this action executes once per chunk. Static state, keyed by the current
 * DML operation, accumulates Ids across chunks while
 * TriggerBase.waitToFinalize() defers the finalizer. On the last chunk
 * TriggerBase.nowFinalize() lets the framework flush exactly one finalizer for
 * the whole DML statement.
 */
public inherited sharing class TA_Opportunity_CollectForErpSync extends MetadataTriggerHandler implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    @TestVisible
    private static final String FINALIZER_NAME = 'OpportunityErpSyncFinalizer';

    /** Ids to sync, accumulated across all chunks of the current DML operation. */
    @TestVisible
    private static Set<Id> pendingOpportunityIds {
        get {
            if (pendingOpportunityIdsByOperation.get(currentDmlKey()) == null) {
                pendingOpportunityIdsByOperation.put(currentDmlKey(), new Set<Id>());
            }
            return pendingOpportunityIdsByOperation.get(currentDmlKey());
        }
    }

    @TestVisible
    private static Map<String, Set<Id>> pendingOpportunityIdsByOperation = new Map<String, Set<Id>>();

    /** Number of chunks already processed for the current DML operation. */
    @TestVisible
    private static Integer processedChunkCount {
        get {
            if (chunkCountByOperation.get(currentDmlKey()) == null) {
                chunkCountByOperation.put(currentDmlKey(), 0);
            }
            return chunkCountByOperation.get(currentDmlKey());
        }
        set { chunkCountByOperation.put(currentDmlKey(), value); }
    }

    @TestVisible
    private static Map<String, Integer> chunkCountByOperation = new Map<String, Integer>();

    /** Chunks seen per operation, used to decide when to flush the finalizer. */
    @TestVisible
    private static Map<String, Integer> expectedChunkCountByOperation = new Map<String, Integer>();

    public TA_Opportunity_CollectForErpSync() {
        // Defer finalizer execution to the end of the DML operation.
        waitToFinalize();
    }

    private static String currentDmlKey() {
        return Request.getCurrentContext() + '-' + System.RequestId(); // hmm, see note below
    }

    public void afterInsert(List<SObject> triggerNew) {
        collect(new List<Opportunity>(triggerNew), null);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        collect(new List<Opportunity>(triggerNew), new List<Opportunity>(triggerOld));
    }

    private void collect(List<Opportunity> newList, List<Opportunity> oldList) {
        for (Integer i = 0; i < newList.size(); i++) {
            Boolean needsSync;
            if (oldList == null) {
                needsSync = true; // after insert: always push
            } else {
                needsSync = newList[i].StageName != oldList[i].StageName;
            }
            if (needsSync) {
                pendingOpportunityIds.add(newList[i].Id);
            }
        }
        processedChunkCount++;
    }

    /**
     * Called by the framework when it is time to hand data to the finalizer.
     * Only flushes on the last chunk so that one DML => one finalizer => one job.
     */
    public override void handleDynamicFinalizers() {
        // no-op: flush is driven by nowFinalize() below
    }
}
