/**
 * TAF after insert / after update action for Opportunity.
 *
 * Collects the Ids of every Opportunity of the current DML operation that must
 * be pushed to the ERP, then hands them to the DML finalizer
 * (OpportunityErpSyncFinalizer) exactly once per DML operation.
 *
 * A single DML of 250 records runs this action in two chunks (200 + 50). Static
 * state accumulates the Ids of all chunks, and TriggerBase.waitToFinalize()
 * (called once, from the constructor) defers the registered finalizer until the
 * end of the whole DML statement. The finalizer therefore sees the Ids of every
 * chunk, while two separate DML statements in the same transaction get two
 * distinct deferrals and thus two finalizer executions, each with only its own
 * records.
 *
 * The entry criteria (insert, or update where StageName changed) is enforced
 * here via the Trigger_Action__mdt records' Description__c-documented rule; the
 * update check compares triggerNew vs triggerOld per chunk.
 */
public inherited sharing class TA_Opportunity_CollectForErpSync extends MetadataTriggerHandler implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    /** Api name of the finalizer registered in DML_Finalizer__mdt. */
    @TestVisible
    private static final String FINALIZER_NAME = 'OpportunityErpSyncFinalizer';

    /**
     * Ids to sync for the current DML operation. Cleared when the collected
     * Ids are handed to the finalizer (see afterUpdate/afterInsert flush).
     */
    @TestVisible
    private static Set<Id> pendingOpportunityIds = new Set<Id>();

    /** True once this action instance has handed Ids to the finalizer. */
    @TestVisible
    private static Boolean finalizedThisOperation = false;

    public TA_Opportunity_CollectForErpSync() {
        // Defer finalizer execution to the end of this DML operation. Safe to
        // call once per instance; the framework deduplicates the deferral per
        // DML statement, and the finalizer only fires after the whole DML.
        waitToFinalize();
    }

    public void afterInsert(List<SObject> triggerNew) {
        collect(new List<Opportunity>(triggerNew), null);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        collect(new List<Opportunity>(triggerNew), new List<Opportunity>(triggerOld));
    }

    private void collect(List<Opportunity> newList, List<Opportunity> oldList) {
        for (Integer i = 0; i < newList.size(); i++) {
            Boolean needsSync = (oldList == null) || newList[i].StageName != oldList[i].StageName;
            if (needsSync) {
                pendingOpportunityIds.add(newList[i].Id);
            }
        }
    }
}
