/**
 * DML-less tests for the TA_Opportunity_GuardAmountDecrease trigger action.
 *
 * Following the Trigger Actions Framework's recommended test pattern: the action's
 * beforeUpdate context method is invoked directly with in-memory records, so the tests
 * perform no DML and no SOQL. New and old records are linked via fake Ids generated
 * with TriggerTestUtility.getFakeId(...), and errors are asserted through the SObject
 * error API (hasErrors() / getErrors()).
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    private static final String ERROR_MESSAGE = TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE;

    /**
     * Builds a new/newer pair of in-memory Opportunity lists that mimic a trigger
     * before-update context. The two lists correspond positionally and share the same
     * fake Ids, exactly as triggerNew and triggerOld do in a real trigger run.
     */
    private static List<Opportunity> buildContext(
        List<Decimal> newAmounts,
        List<Decimal> oldAmounts
    ) {
        List<Opportunity> triggerNew = new List<Opportunity>();
        List<Opportunity> triggerOld = new List<Opportunity>();
        for (Integer i = 0; i < newAmounts.size(); i++) {
            Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
            triggerOld.add(new Opportunity(
                Id = fakeId,
                Amount = oldAmounts[i]
            ));
            triggerNew.add(new Opportunity(
                Id = fakeId,
                Amount = newAmounts[i]
            ));
        }
        // Expose both lists to the caller by storing them in a returned holder.
        newContextLists = triggerNew;
        return triggerOld;
    }

    @TestVisible
    private static List<Opportunity> newContextLists;

    private static void runAction() {
        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(newContextLists, oldContextLists);
    }

    @TestVisible
    private static List<Opportunity> oldContextLists;

    private static void assertNoErrors(Opportunity opp) {
        Assert.isTrue(
            !opp.hasErrors(),
            'Expected record to be accepted, but it had errors: ' + opp.getErrors()
        );
    }

    private static void assertSingleError(Opportunity opp) {
        Assert.isTrue(opp.hasErrors(), 'Expected the record to be rejected with an error.');
        List<Database.Error> errors = opp.getErrors();
        Assert.areEqual(1, errors.size(), 'Expected exactly one error on the record.');
        Assert.areEqual(
            ERROR_MESSAGE,
            errors[0].getMessage(),
            'Error message did not match the action''s ERROR_MESSAGE constant.'
        );
    }

    @IsTest
    static void testReductionOfMoreThanHalfIsRejected() {
        List<Opportunity> oldList = buildContext(
            new List<Decimal>{ 499 },
            new List<Decimal>{ 1000 }
        );
        oldContextLists = oldList;
        runAction();
        assertSingleError(newContextLists[0]);
    }

    @IsTest
    static void testReductionOfExactlyHalfIsAccepted() {
        List<Opportunity> oldList = buildContext(
            new List<Decimal>{ 500 },
            new List<Decimal>{ 1000 }
        );
        oldContextLists = oldList;
        runAction();
        assertNoErrors(newContextLists[0]);
    }

    @IsTest
    static void testIncreaseIsAccepted() {
        List<Opportunity> oldList = buildContext(
            new List<Decimal>{ 1500 },
            new List<Decimal>{ 1000 }
        );
        oldContextLists = oldList;
        runAction();
        assertNoErrors(newContextLists[0]);
    }

    @IsTest
    static void testNullPreviousAmountIsAccepted() {
        List<Opportunity> oldList = buildContext(
            new List<Decimal>{ 750 },
            new List<Decimal>{ null }
        );
        oldContextLists = oldList;
        runAction();
        assertNoErrors(newContextLists[0]);
    }

    @IsTest
    static void testMixedRecordsOnlyViolatorsGetErrors() {
        // 0: increase -> OK, 1: reduction > half -> error,
        // 2: reduction of exactly half -> OK, 3: null previous -> OK,
        // 4: reduction > half -> error, 5: null new amount -> OK.
        List<Opportunity> oldList = buildContext(
            new List<Decimal>{ 2000, 400, 500, 100, null, 400 },
            new List<Decimal>{ 1000, 1000, 1000, null, 1000, 1000 }
        );
        oldContextLists = oldList;
        runAction();

        List<Integer> violatingIndexes = new List<Integer>{ 1, 4 };
        for (Integer i = 0; i < newContextLists.size(); i++) {
            if (violatingIndexes.contains(i)) {
                assertSingleError(newContextLists[i]);
            } else {
                assertNoErrors(newContextLists[i]);
            }
        }
    }
}
