/**
 * @description Trigger action which normalizes contact information on Leads
 *              as they are inserted. Cleans the Email (trim + lowercase, null-safe)
 *              and Company (trim) fields and defaults LeadSource to 'Web' when
 *              it is blank, preserving any existing value. Runs synchronously in
 *              the before insert context so that the clean values are persisted
 *              with the very first DML — no additional DML or SOQL is performed.
 * @group Trigger Actions Framework
 */
public inherited sharing class TA_Lead_NormalizeContactInfo
    implements TriggerAction.BeforeInsert {

    private static final String DEFAULT_LEAD_SOURCE = 'Web';

    /**
     * @description Normalizes Email, Company and LeadSource for every Lead in
     *              the triggering batch. Mutates the in-memory records of the
     *              before insert context so Salesforce persists the cleaned
     *              values directly, handling full trigger batches (e.g. 200
     *              records) with a single pass and no extra DML or SOQL.
     * @param triggerNew The list of new Leads being inserted.
     */
    public void beforeInsert(List<SObject> triggerNew) {
        for (SObject record : triggerNew) {
            Lead lead = (Lead) record;
            lead.Email = normalizeEmail(lead.Email);
            lead.Company = trimToNull(lead.Company);
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = DEFAULT_LEAD_SOURCE;
            }
        }
    }

    /**
     * @description Trims surrounding whitespace and lower-cases an email
     *              address, returning null when the input is null or blank so
     *              that a null email stays null instead of becoming ''.
     * @param email The raw email value.
     * @return The normalized email, or null when no usable value was provided.
     */
    private String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }

    /**
     * @description Trims surrounding whitespace from a company name, mapping a
     *              blank result to null so empty whitespace-only input is not
     *              persisted as a zero-length string.
     * @param company The raw company value.
     * @return The trimmed company name, or null when it was blank.
     */
    private String trimToNull(String company) {
        if (String.isBlank(company)) {
            return null;
        }
        return company.trim();
    }
}
