/**
 * Singleton query helper for Contact trigger actions.
 *
 * Loads the parent Accounts for the contacts in the trigger exactly once per
 * trigger execution and exposes them via `accountsById` so that multiple
 * trigger actions can share the data without issuing repeated SOQL queries.
 *
 * The inner `Service` class is registered as the first Before Insert trigger
 * action (Order__c = 1) and (re)loads the map at the start of every execution,
 * so any later DML in the same transaction - which may involve other accounts -
 * is always reflected in the map.
 */
public inherited sharing class TA_Contact_Queries {

	/**
	 * Parent Accounts of the contacts in the current trigger execution,
	 * keyed by Account Id. Populated by the inner `Service` action.
	 */
	public Map<Id, Account> accountsById;

	private static TA_Contact_Queries instance;

	private TA_Contact_Queries() {
		accountsById = new Map<Id, Account>();
	}

	public static TA_Contact_Queries getInstance() {
		if (instance == null) {
			instance = new TA_Contact_Queries();
		}
		return instance;
	}

	/**
	 * Loads the Accounts referenced by the given contacts in a single query.
	 * Called by the `Service` trigger action at the start of every trigger
	 * execution, replacing any previously loaded data.
	 */
	public void loadAccounts(List<Contact> contacts) {
		accountsById = new Map<Id, Account>();
		Set<Id> accountIds = new Set<Id>();
		for (Contact contact : contacts) {
			if (contact.AccountId != null) {
				accountIds.add(contact.AccountId);
			}
		}
		if (!accountIds.isEmpty()) {
			accountsById.putAll([
				SELECT Id,
					BillingStreet,
					BillingCity,
					BillingPostalCode,
					BillingCountry,
					AccountSource
				FROM Account
				WHERE Id IN :accountIds
			]);
		}
	}

	/**
	 * Trigger action that must run first in before insert: it loads the
	 * shared Account data used by all subsequent actions.
	 */
	public inherited sharing class Service implements TriggerAction.BeforeInsert {

		public void beforeInsert(List<SObject> triggerNew) {
			if (Trigger.isExecuting && Trigger.isBefore && Trigger.isInsert) {
				getInstance().loadAccounts((List<Contact>) triggerNew);
			}
		}
	}
}
