/**
 * Contact before-insert action: when a new contact has an Account and all four
 * mailing address fields are blank, inherit the account's billing address.
 *
 * Relies on TA_Contact_Queries.Service (Order__c = 1) having loaded the parent
 * accounts, so this action performs no SOQL of its own.
 */
public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {

	public void beforeInsert(List<SObject> triggerNew) {
		Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
		for (Contact contact : (List<Contact>) triggerNew) {
			if (contact.AccountId == null) {
				continue;
			}
			Boolean mailingStreetIsBlank = contact.MailingStreet == null;
			Boolean mailingCityIsBlank = contact.MailingCity == null;
			Boolean mailingPostalCodeIsBlank = contact.MailingPostalCode == null;
			Boolean mailingCountryIsBlank = contact.MailingCountry == null;
			Boolean hasMailingAddress =
				!(mailingStreetIsBlank && mailingCityIsBlank &&
					mailingPostalCodeIsBlank && mailingCountryIsBlank);
			if (hasMailingAddress) {
				continue;
			}
			Account account = accountsById.get(contact.AccountId);
			if (account == null) {
				continue;
			}
			contact.MailingStreet = account.BillingStreet;
			contact.MailingCity = account.BillingCity;
			contact.MailingPostalCode = account.BillingPostalCode;
			contact.MailingCountry = account.BillingCountry;
		}
	}
}
